import os, sys, math, re, json

ESC = "\x1b"

def write_stdout(data):
    if isinstance(data, str):
        data = data.encode("utf-8", "surrogateescape")
    if not data:
        return
    try:
        view = memoryview(data)
        while view:
            n = os.write(1, view)
            if n <= 0:
                raise OSError("write failed")
            view = view[n:]
    except BrokenPipeError:
        # The reference exits silently with status 14 on output errors.
        try:
            os.close(1)
        except Exception:
            pass
        os._exit(14)
    except OSError:
        os._exit(14)

def write_stderr(data):
    if isinstance(data, str):
        data = data.encode("utf-8", "surrogateescape")
    try:
        view = memoryview(data)
        while view:
            n = os.write(2, view)
            view = view[n:]
    except Exception:
        pass

class RustPanic(Exception):
    def __init__(self, location, message):
        super().__init__(message)
        self.location = location
        self.message = message

def panic(location, message):
    raise RustPanic(location, message)

def emit_panic(location, message):
    # Rust (new versions) prints: \nthread 'main' (<tid>) panicked at <loc>:\n<msg>\nnote: ...
    # The parenthesised number is the main thread id, which on Linux is the pid.
    text = f"\nthread 'main' ({os.getpid()}) panicked at {location}:\n{message}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n"
    write_stderr(text)

def ansi(code, s):
    return f"{ESC}[{code}m{s}{ESC}[0m"

def fmt_f64(x):
    x = float(x)
    if math.isnan(x):
        return "NaN"
    if math.isinf(x):
        return "inf" if x > 0 else "-inf"
    s = repr(x)
    if "e" in s or "E" in s:
        mant, exp = re.split("[eE]", s)
        ei = int(exp)
        return f"{mant}e{ei:+d}"
    return s

def scalar_to_string(v):
    """Object scalar -> string (strings raw)."""
    if isinstance(v, str):
        return v
    if v is True:
        return "true"
    if v is False:
        return "false"
    if v is None:
        return "null"
    if isinstance(v, float):
        return fmt_f64(v)
    if isinstance(v, int):
        return str(v)
    return ""

def json_quote(s):
    # Compact JSON string like serde_json (ensure_ascii=False closest).
    return json.dumps(s, ensure_ascii=False, separators=(",", ":"))

def json_scalar_to_string(v):
    """Value::to_string() for scalars: strings are JSON quoted."""
    if isinstance(v, str):
        return json_quote(v)
    return scalar_to_string(v)

def rust_json_compact(v):
    """Compact JSON serialisation used where Value::to_string applies to any value."""
    if isinstance(v, dict):
        return "{" + ",".join(json_quote(k) + ":" + rust_json_compact(val) for k, val in v.items()) + "}"
    if isinstance(v, list):
        return "[" + ",".join(rust_json_compact(x) for x in v) + "]"
    return json_scalar_to_string(v)

# ---------- JSON parsing (serde_json compatible in the ways we need) ----------
class JsonError(Exception):
    pass

def _parse_int(tok):
    if tok == "-0":
        return -0.0
    try:
        n = int(tok)
    except Exception as e:
        raise JsonError(str(e))
    if -(2**63) <= n <= 2**64 - 1:
        return n
    try:
        f = float(tok)
    except Exception as e:
        raise JsonError(str(e))
    if math.isinf(f):
        raise JsonError("number out of range")
    return f

def _parse_float(tok):
    f = float(tok)
    if math.isinf(f):
        raise JsonError("number out of range")
    return f

def _parse_constant(tok):
    raise JsonError("invalid constant")

def _object_pairs(pairs):
    d = {}
    for k, v in pairs:
        d[k] = v
    return {k: d[k] for k in sorted(d.keys())}

def _max_depth(s):
    depth = 0
    maxd = 0
    in_str = False
    esc = False
    for ch in s:
        if in_str:
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == '"':
                in_str = False
            continue
        if ch == '"':
            in_str = True
        elif ch in "[{":
            depth += 1
            if depth > maxd:
                maxd = depth
        elif ch in "]}":
            depth -= 1
    return maxd

def _has_surrogate(v):
    stack = [v]
    while stack:
        x = stack.pop()
        if isinstance(x, str):
            for ch in x:
                o = ord(ch)
                if 0xD800 <= o <= 0xDFFF:
                    return True
        elif isinstance(x, dict):
            for k, val in x.items():
                stack.append(k); stack.append(val)
        elif isinstance(x, list):
            stack.extend(x)
    return False

_decoder = json.JSONDecoder(parse_int=_parse_int, parse_float=_parse_float,
                             parse_constant=_parse_constant, object_pairs_hook=_object_pairs)

def parse_json(s):
    if _max_depth(s) > 127:
        raise JsonError("recursion limit exceeded")
    try:
        v = _decoder.decode(s)
    except JsonError:
        raise
    except Exception as e:
        raise JsonError(str(e))
    if _has_surrogate(v):
        raise JsonError("lone surrogate")
    return v

# ---------- timestamp handling ----------
def _civil_from_days(z):
    # Howard Hinnant's algorithm; z is days since 1970-01-01.
    z += 719468
    era = (z if z >= 0 else z - 146096) // 146097
    doe = z - era * 146097
    yoe = (doe - doe // 1460 + doe // 36524 - doe // 146096) // 365
    y = yoe + era * 400
    doy = doe - (365 * yoe + yoe // 4 - yoe // 100)
    mp = (5 * doy + 2) // 153
    d = doy - (153 * mp + 2) // 5 + 1
    m = mp + 3 if mp < 10 else mp - 9
    y += 1 if m <= 2 else 0
    return y, m, d

_CHRONO_MIN_MS = -8334601228800000
_CHRONO_MAX_MS = 8210266876799999

def format_ms_rfc3339(ms):
    days, rem = divmod(ms, 86400000)
    secs, millis = divmod(rem, 1000)
    hh, rem2 = divmod(secs, 3600)
    mm, ss = divmod(rem2, 60)
    y, mo, d = _civil_from_days(days)
    if 0 <= y <= 9999:
        ys = f"{y:04d}"
    elif y > 9999:
        ys = f"+{y}"
    else:
        ys = f"-{abs(y):04d}"
    return f"{ys}-{mo:02d}-{d:02d}T{hh:02d}:{mm:02d}:{ss:02d}.{millis:03d}Z"

import time as _time

def convert_timestamp(s):
    if not re.fullmatch(r"[+-]?[0-9]+", s or ""):
        return s
    try:
        v = int(s)
    except Exception:
        return s
    if v < -(2**63) or v > 2**63 - 1:
        return s
    now_ms = _time.time_ns() // 1000000
    sec_ms = v * 1000
    ms_ms = v
    sec_ok = _CHRONO_MIN_MS <= sec_ms <= _CHRONO_MAX_MS
    ms_ok = _CHRONO_MIN_MS <= ms_ms <= _CHRONO_MAX_MS
    if sec_ok and ms_ok:
        # Choose the interpretation closest to now (seconds wins ties).
        if abs(sec_ms - now_ms) <= abs(ms_ms - now_ms):
            chosen = sec_ms
        else:
            chosen = ms_ms
        return format_ms_rfc3339(chosen)
    if ms_ok:
        return format_ms_rfc3339(ms_ms)
    if sec_ok:
        return format_ms_rfc3339(sec_ms)
    return s
