import re, math, json
from util import ansi, fmt_f64, scalar_to_string, RustPanic

# ---------------- errors ----------------
class TemplateSyntaxError(Exception):
    def __init__(self, reason, line_no=1, column_no=1, preformatted_reason=None):
        super().__init__(reason)
        self.reason = reason
        self.line_no = line_no
        self.column_no = column_no
        self.preformatted_reason = preformatted_reason  # e.g. MismatchingClosedHelper(...)
    def debug(self, template_name, source):
        lines = source.split("\n")
        line = lines[self.line_no-1] if 1 <= self.line_no <= len(lines) else ""
        marker = "".join("^" if i == self.column_no else "-" for i in range(len(line)))
        segment = f"{self.line_no-1:4d} | {line}\n     |{marker}\n"
        if self.preformatted_reason:
            reason = self.preformatted_reason
        else:
            reason = f"InvalidSyntax({_rust_debug_str(self.reason)})"
        return ("TemplateError { reason: " + reason +
                f", template_name: Some({_rust_debug_str(template_name)}), line_no: Some({self.line_no}), "
                f"column_no: Some({self.column_no}), segment: Some({_rust_debug_str(segment)}) }}")

def _rust_debug_str(s):
    out = ['"']
    for ch in s:
        if ch == '"': out.append('\\"')
        elif ch == '\\': out.append('\\\\')
        elif ch == '\n': out.append('\\n')
        elif ch == '\r': out.append('\\r')
        elif ch == '\t': out.append('\\t')
        elif ord(ch) < 0x20 or ord(ch) == 0x7f: out.append('\\u{%x}' % ord(ch))
        else: out.append(ch)
    out.append('"')
    return "".join(out)

class RenderError(Exception):
    def __init__(self, detail, line=1, col=1):
        super().__init__(detail)
        self.detail = detail
        self.line = line
        self.col = col
    def full(self, template_name):
        return f'Error rendering "{template_name}" line {self.line}, col {self.col}: {self.detail}'

# ---------------- expression AST ----------------
class Literal:
    def __init__(self, value): self.value = value
class Path:
    def __init__(self, raw): self.raw = raw
class SubExpr:
    def __init__(self, call): self.call = call
class Call:
    def __init__(self, name, args=None, hash_=None, block_params=None):
        self.name = name  # str (path raw) or Path
        self.args = args or []
        self.hash = hash_ or {}
        self.block_params = block_params or []

class Text:
    def __init__(self, text): self.text = text
class ExprNode:
    def __init__(self, call, line, col):
        self.call = call; self.line = line; self.col = col
class BlockNode:
    def __init__(self, call, line, col):
        self.call = call; self.line = line; self.col = col
        self.body = []; self.inverse = []
class PartialNode:
    def __init__(self, name, line, col): self.name=name; self.line=line; self.col=col
class DecoratorNode:
    def __init__(self, name, line, col): self.name=name; self.line=line; self.col=col
class RawTextNode:
    def __init__(self, text): self.text=text

# ---------------- expression tokenising / parsing ----------------

def _line_col(src, pos):
    line = src.count("\n", 0, pos) + 1
    last = src.rfind("\n", 0, pos)
    col = pos - last  # 1-based char col (pos-last: if last=-1 col=pos+1)
    return line, col

class ExprParser:
    def __init__(self, text, src, base_pos):
        self.s = text
        self.i = 0
        self.src = src
        self.base = base_pos
    def error(self, reason, at=None):
