                if not exprtext:
                    ln, cl = _line_col(src, idx+3)
                    raise TemplateSyntaxError("expected identifier", ln, cl+1)
                ep = ExprParser(exprtext, src, idx+2)
                call = ep.parse_call()
                blk = BlockNode(call, line, col)
                cur_nodes().append(blk)
                stack.append({"nodes": None, "block": blk, "close": _call_name(call), "in_inverse": False})
            elif first == "/":
                cname = s[1:].strip()
                # name may be path; take first word/segment as written
                cname = cname.split()[0] if cname.split() else ""
                if len(stack) == 1:
                    ln, cl = _line_col(src, idx+2)
                    raise TemplateSyntaxError("expected identifier, subexpression, leading_tilde_to_omit_whitespace, or path_inline", ln, cl+1)
                fr = stack[-1]
                expected = fr["close"]
                if cname != expected:
                    pre = f"MismatchingClosedHelper({_rust_debug_str(expected)}, {_rust_debug_str(cname)})"
                    raise TemplateSyntaxError("", line, col, preformatted_reason=pre)
                stack.pop()
            elif s == "^":
