        return self.s[self.i] if self.i < len(self.s) else ""
    def parse_call(self, top=False):
        """Parse: head arg* hash* (block params) - used for expressions and subexpressions."""
        self.skip()
        if self.i >= len(self.s):
            self.error("expected identifier, subexpression, leading_tilde_to_omit_whitespace, or path_inline")
        # head
        head = self.parse_param(head=True)
        args = []
        hash_ = {}
        block_params = []
        while True:
            self.skip()
            if self.i >= len(self.s) or self.peek() == ")":
                break
            # block params: as |x y|
            save = self.i
            word = self._peek_word()
            if word == "as":
                self.i += 2
                self.skip()
                if self.peek() == "|":
                    self.i += 1
                    while True:
                        self.skip()
                        if self.peek() == "|":
                            self.i += 1; break
                        if self.i >= len(self.s):
                            self.error("expected identifier")
                        block_params.append(self._read_word())
                    continue
                else:
                    self.i = save
            # hash param?  name = value  (identifier followed by '=')
            m = re.match(r"[A-Za-z_][A-Za-z0-9_-]*=", self.s[self.i:])
            if m and not self._at_path_context():
                key = m.group(0)[:-1]
                self.i += len(m.group(0))
                val = self.parse_param()
                hash_[key] = val
                continue
            args.append(self.parse_param())
        # build call
        if isinstance(head, Path):
            name = head.raw
        elif isinstance(head, SubExpr):
            if args or hash_:
                self.error("expected identifier")
            return head.call
        else:
            # literal head with no args is not a call; represent as a special call returning it
            if not args and not hash_:
                return Call("__literal__", [head])
            self.error("expected identifier, subexpression, leading_tilde_to_omit_whitespace, or path_inline")
        return Call(name, args, hash_, block_params)
    def _at_path_context(self):
        return False
    def _peek_word(self):
        m = re.match(r"[^\s)]+", self.s[self.i:])
        return m.group(0) if m else ""
    def _read_word(self):
        m = re.match(r"[^\s)|]+", self.s[self.i:])
        w = m.group(0); self.i += len(w); return w
    def parse_param(self, head=False):
        self.skip()
        if self.i >= len(self.s):
            self.error("expected identifier, helper_parameter, or trailing_tilde_to_omit_whitespace")
        c = self.peek()
        if c == "(":
            self.i += 1
            inner = self.parse_call()
            self.skip()
            if self.peek() != ")":
                self.error("expected helper_parameter")
            self.i += 1
            return SubExpr(inner)
        if c in "\"'":
            return Literal(self._parse_string())
        if c in "[{":
            # Try JSON literal first (but a leading [..] path segment is also possible)
            lit = self._try_json_literal()
            if lit is not _NO_JSON:
                return Literal(lit)
            # fall through to path reading
            return Path(self._read_path())
        # bare word / path / number / bool / null
        w = self._read_path()
        if w == "true": return Literal(True)
        if w == "false": return Literal(False)
        if w == "null" or w == "undefined": return Literal(None)
        if re.fullmatch(r"-?(0|[0-9]+)(\.[0-9]+)?([eE][+-]?[0-9]+)?", w) and _looks_like_number(w):
            return Literal(_parse_json_number_token(w))
        if w == ".":
            self.error("expected identifier, subexpression, leading_tilde_to_omit_whitespace, or path_inline", at=self.i-1)
        if w == "":
            self.error("expected identifier, subexpression, leading_tilde_to_omit_whitespace, or path_inline")
        return Path(w)
    def _parse_string(self):
        q = self.s[self.i]; self.i += 1
        out = []
        while self.i < len(self.s):
            c = self.s[self.i]; self.i += 1
            if c == q:
                return "".join(out)
            if c == "\\" and self.i < len(self.s):
                nxt = self.s[self.i]; self.i += 1
                esc = {"n":"\n","t":"\t","r":"\r","b":"\b","f":"\f","\\":"\\","\"":'"',"'":"'","/":"/"}
                if nxt == "u" and self.i < len(self.s) and self.s[self.i] == "{":
                    end = self.s.find("}", self.i)
                    if end != -1:
                        try: out.append(chr(int(self.s[self.i+1:end], 16)))
                        except Exception: out.append("u")
                        self.i = end+1; continue
                if nxt == "u" and self.i+4 <= len(self.s):
                    try: out.append(chr(int(self.s[self.i:self.i+4], 16))); self.i += 4; continue
                    except Exception: pass
                out.append(esc.get(nxt, nxt))
            else:
                out.append(c)
        self.error("expected identifier, helper_parameter, or trailing_tilde_to_omit_whitespace")
    def _try_json_literal(self):
        # Only treat as JSON when it parses fully as JSON and (contains ',' or ':' or starts with '{' or is empty containers or numeric content)
        start = self.i
        depth = 0; in_str = False; esc = False; q = ""
        j = self.i
        while j < len(self.s):
            ch = self.s[j]
            if in_str:
                if esc: esc=False
                elif ch == "\\": esc=True
                elif ch == q: in_str=False
            else:
                if ch in "\"'": in_str=True; q=ch
                elif ch in "[{": depth += 1
                elif ch in "]}":
                    depth -= 1
                    if depth == 0:
                        cand = self.s[start:j+1]
                        # [foo] style path segment should not be JSON
                        try:
                            val = json.loads(cand)
                        except Exception:
                            return _NO_JSON
                        # If it is like [123] it could be a path segment when head; JSON only if not a single scalar in a bracket at head position?
                        self.i = j+1
                        return val
                elif ch in " \t" and depth == 0:
                    break
            j += 1
        return _NO_JSON
    def _read_path(self):
        start = self.i
        # consume until whitespace or ')' respecting [ ] segments (with possible spaces inside)
        while self.i < len(self.s):
            c = self.s[self.i]
            if c == "[":
                end = self.s.find("]", self.i)
                if end == -1:
                    self.i = len(self.s); break
                self.i = end+1
                continue
            if c in " \t\r\n)":
                break
            if c == "=":
                break
            self.i += 1
        return self.s[start:self.i]

class _NoJson: pass
_NO_JSON = _NoJson()

def _looks_like_number(w):
    return bool(re.fullmatch(r"-?[0-9]+(\.[0-9]+)?([eE][+-]?[0-9]+)?", w))

def _parse_json_number_token(w):
    if "." in w or "e" in w or "E" in w:
        f = float(w)
        return f
    if w == "-0":
        return -0.0
    try:
        return int(w)
    except Exception:
        return float(w)

# ---------------- template parser ----------------
class Template:
    def __init__(self, source, name):
        self.source = source
        self.name = name
        self.nodes = []
        self._parse()
    def _parse(self):
        src = self.source
        # parser stack of frames: dict {nodes, block, close_name, in_inverse}
        root_nodes = []
        stack = [{"nodes": root_nodes, "block": None, "close": None, "in_inverse": False}]
        pending_rtrim = False
        i = 0
        n = len(src)
        def cur_nodes():
            fr = stack[-1]
            if fr["block"] is not None:
                return fr["block"].inverse if fr["in_inverse"] else fr["block"].body
            return fr["nodes"]
        def add_text(t):
            nonlocal pending_rtrim
            if pending_rtrim:
                t = t.lstrip(" \t\r\n")
                pending_rtrim = False
            if t:
                cur_nodes().append(Text(t))
        while i < n:
            idx = src.find("{{", i)
            if idx == -1:
                add_text(src[i:])
                i = n; break
            # escaped \{{  (a single backslash immediately before)
            if idx > 0 and src[idx-1] == "\\" and (idx < 2 or src[idx-2] != "\\"):
                add_text(src[i:idx-1] + "{{")
                i = idx+2
                continue
            if idx > i:
                add_text(src[i:idx])
            elif pending_rtrim:
                # no text in between; clear flag? rtrim applies to next text whatever
                pass
            line, col = _line_col(src, idx)
            # comments
            if src.startswith("{{!--", idx):
                end = src.find("--}}", idx)
                if end == -1:
                    line2, col2 = _line_col(src, n)
                    raise TemplateSyntaxError("expected hbs_comment", line2, col2)
                # tilde handling within comments is ignored
                i = end+4
                continue
            if src.startswith("{{!", idx):
                end = src.find("}}", idx)
                if end == -1:
                    line2, col2 = _line_col(src, n)
                    raise TemplateSyntaxError("expected hbs_comment_compact", line2, col2)
                i = end+2
                continue
            # raw block {{{{name}}}} ... {{{{/name}}}}
            if src.startswith("{{{{", idx) and not src.startswith("{{{{/", idx):
                end = src.find("}}}}", idx)
                if end == -1:
                    line2, col2 = _line_col(src, n)
                    raise TemplateSyntaxError("expected raw_block_start", line2, col2)
                inner = src[idx+4:end].strip()
                # helper name is first word
                rname = inner.split()[0] if inner.split() else ""
                close_marker = "{{{{/" + rname + "}}}}"
                cidx = src.find(close_marker, end+4)
                if cidx == -1:
                    line2, col2 = _line_col(src, n)
                    raise TemplateSyntaxError("expected escape or raw_block_end", line2, col2)
                content = src[end+4:cidx]
                if rname == "raw":
                    add_text_raw = content.lstrip(" \t\r\n")
                    if pending_rtrim:
                        add_text_raw = add_text_raw.lstrip(" \t\r\n"); pending_rtrim=False
                    cur_nodes().append(RawTextNode(add_text_raw))
                else:
                    # treat as block call with raw content body: unknown helpers will error at render
                    ep = ExprParser(inner, src, idx+4)
                    call = ep.parse_call()
                    blk = BlockNode(call, line, col)
                    blk.body.append(RawTextNode(content.lstrip(" \t\r\n")))
                    cur_nodes().append(blk)
                i = cidx + len(close_marker)
                continue
            # find closing }} (or }} } for triple)
            triple = src.startswith("{{{", idx)
            if triple:
                end = src.find("}}}", idx)
                if end == -1:
                    line2, col2 = _line_col(src, n)
                    # {{{msg}} -> expected trailing_tilde...
                    raise TemplateSyntaxError("expected trailing_tilde_to_omit_whitespace", line2, col2)
                inner = src[idx+3:end]
                after = end+3
            else:
                end = self._find_close(src, idx+2)
                if end == -1:
                    line2, col2 = _line_col(src, n)
                    raise TemplateSyntaxError("expected identifier, helper_parameter, or trailing_tilde_to_omit_whitespace", line2, col2)
                inner = src[idx+2:end]
                after = end+2
            # whitespace tilde
            ltrim = False; rtrim = False
            inner_stripped = inner
            if inner_stripped.startswith("~"):
                ltrim = True; inner_stripped = inner_stripped[1:]
            if inner_stripped.rstrip(" \t").endswith("~"):
                # trailing ~ before }} (possibly ' ~')
                rtrim = True
                # remove that ~
                j = inner_stripped.rfind("~")
                inner_stripped = inner_stripped[:j] + inner_stripped[j+1:]
            if ltrim:
                self._trim_prev(cur_nodes())
            i = after
            # discriminate by first nonspace char
            s = inner_stripped.strip()
            if s == "":
                # column: position of first } (or after spaces)
                p = idx+2 + (len(inner) - len(inner.lstrip()))
                ln, cl = _line_col(src, min(p+1, n-1) if n else 0)
                raise TemplateSyntaxError("expected identifier, subexpression, leading_tilde_to_omit_whitespace, or path_inline", ln, cl)
            first = s[0]
            if first == "#":
                exprtext = s[1:].strip()
                if not exprtext:
                    ln, cl = _line_col(src, idx+3)
                    raise TemplateSyntaxError("expected identifier", ln, cl+1)
                ep = ExprParser(exprtext, src, idx+2)
                call = ep.parse_call()
                blk = BlockNode(call, line, col)
                cur_nodes().append(blk)
                stack.append({"nodes": None, "block": blk, "close": _call_name(call), "in_inverse": False})
            elif first == "/":
                cname = s[1:].strip()
                # name may be path; take first word/segment as written
                cname = cname.split()[0] if cname.split() else ""
                if len(stack) == 1:
                    ln, cl = _line_col(src, idx+2)
                    raise TemplateSyntaxError("expected identifier, subexpression, leading_tilde_to_omit_whitespace, or path_inline", ln, cl+1)
                fr = stack[-1]
                expected = fr["close"]
                if cname != expected:
                    pre = f"MismatchingClosedHelper({_rust_debug_str(expected)}, {_rust_debug_str(cname)})"
                    raise TemplateSyntaxError("", line, col, preformatted_reason=pre)
                stack.pop()
            elif s == "^":
                if len(stack) == 1 or stack[-1]["in_inverse"]:
                    ln, cl = _line_col(src, idx+2)
                    raise TemplateSyntaxError("unexpected invert_tag_item; expected leading_tilde_to_omit_whitespace", ln, cl+1)
                stack[-1]["in_inverse"] = True
            elif s == "else" or s.startswith("else ") or s.startswith("else\t"):
                if len(stack) == 1 or stack[-1]["in_inverse"]:
                    ln, cl = _line_col(src, idx+2)
                    raise TemplateSyntaxError("unexpected invert_tag_item; expected leading_tilde_to_omit_whitespace", ln, cl+1)
                rest = s[4:].strip()
                stack[-1]["in_inverse"] = True
                if rest:
                    # chained else: {{else if ...}}
                    ep = ExprParser(rest, src, idx+2)
                    call = ep.parse_call()
                    blk = BlockNode(call, line, col)
                    cur_nodes().append(blk)
                    fr = stack.pop()
                    # new frame uses original close name
                    stack.append({"nodes": None, "block": blk, "close": fr["close"], "in_inverse": False})
            elif first == ">":
                rest = s[1:].strip()
                if not rest:
                    ln, cl = _line_col(src, idx+3)
                    raise TemplateSyntaxError("expected partial_identifier, subexpression, or path_inline", ln, cl+1)
                pname = rest.split()[0]
                cur_nodes().append(PartialNode(pname, line, col))
            elif first == "*":
                rest = s[1:].strip()
                if not rest:
                    ln, cl = _line_col(src, idx+3)
                    raise TemplateSyntaxError("expected identifier", ln, cl+1)
                dname = rest.split()[0]
                cur_nodes().append(DecoratorNode(dname, line, col))
            elif first == "^":
                # {{^if ...}} handled as invalid in reference ("expected keywords")
                ln, cl = _line_col(src, idx+10 if idx+10 < n else idx)
                raise TemplateSyntaxError("expected keywords", ln, cl)
            elif first == "&":
                exprtext = s[1:].strip()
                ep = ExprParser(exprtext, src, idx+2)
                call = ep.parse_call()
                cur_nodes().append(ExprNode(call, line, col))
            else:
                # {{^if}} check (first char ^ but s != ^ and not handled): rust errors 'expected keywords'
                if first == "^":
                    ln, cl = _line_col(src, idx+2)
                    raise TemplateSyntaxError("expected keywords", ln, idx+11)
                ep = ExprParser(s, src, idx+2)
                call = ep.parse_call()
                # single '/' etc are caught by path validation in parse_call for "."
                cur_nodes().append(ExprNode(call, line, col))
            if rtrim:
                pending_rtrim = True
        if len(stack) > 1:
            line2, col2 = _line_col(src, n)
            raise TemplateSyntaxError("expected escape, expression, html_expression, decorator_expression, partial_expression, invert_tag, invert_chain_tag, helper_block_start, helper_block_end, decorator_block_start, partial_block_start, raw_block_start, hbs_comment, or hbs_comment_compact", line2, col2)
        self.nodes = root_nodes
    @staticmethod
    def _find_close(src, start):
        i = start; q = None; esc = False
        while i < len(src)-1:
            c = src[i]
            if q:
                if esc: esc=False
                elif c == "\\": esc=True
                elif c == q: q=None
            else:
                if c in "\"'": q=c
                elif c == "}" and src[i+1] == "}":
                    return i
            i += 1
        return -1
    @staticmethod
    def _trim_prev(nodes):
        if nodes and isinstance(nodes[-1], Text):
            nodes[-1].text = nodes[-1].text.rstrip(" \t\r\n")
            if nodes[-1].text == "":
                nodes.pop()
    # ---------- rendering ----------
    def render(self, data):
        frames = [{"value": data, "block_params": {}, "data": {}}]
        out = []
        self._render_nodes(self.nodes, frames, out)
        return "".join(out)
    def _render_nodes(self, nodes, frames, out):
        for node in nodes:
            if isinstance(node, Text) or isinstance(node, RawTextNode):
                out.append(node.text)
            elif isinstance(node, PartialNode):
                raise RenderError(f"Partial not found {node.name}", node.line, node.col)
            elif isinstance(node, DecoratorNode):
                raise RenderError(f"Decorator not found {node.name}", node.line, node.col)
            elif isinstance(node, ExprNode):
                val = self._eval_call(node.call, frames, node.line, node.col, block=None)
                out.append(render_value(val))
            elif isinstance(node, BlockNode):
                self._render_block(node, frames, out)
    def _render_block(self, node, frames, out):
        name = _call_name(node.call)
        if name == "if" or name == "unless":
            if len(node.call.args) < 1:
                raise RenderError("Helper/Decorator if param at index 0 required but not found", node.line, node.col)
            val = self._eval_param(node.call.args[0], frames, node.line, node.col)
            include_zero = False
            if "includeZero" in node.call.hash:
                hv = self._eval_param(node.call.hash["includeZero"], frames, node.line, node.col)
                include_zero = hv is True
            cond = is_truthy(val, include_zero)
            if name == "unless": cond = not cond
            self._render_nodes(node.body if cond else node.inverse, frames, out)
            return
        if name == "with":
            if len(node.call.args) < 1:
                raise RenderError("Helper/Decorator with param at index 0 required but not found", node.line, node.col)
            val = self._eval_param(node.call.args[0], frames, node.line, node.col)
            if is_truthy(val, False):
                bp = {}
                if node.call.block_params:
                    bp[node.call.block_params[0]] = val
                frames.append({"value": val, "block_params": bp, "data": {}})
                try: self._render_nodes(node.body, frames, out)
                finally: frames.pop()
            else:
                self._render_nodes(node.inverse, frames, out)
            return
        if name == "each":
            if len(node.call.args) < 1:
                raise RenderError("Helper/Decorator each param at index 0 required but not found", node.line, node.col)
            val = self._eval_param(node.call.args[0], frames, node.line, node.col)
            items = []
            if isinstance(val, list):
                items = [(idx, None, v) for idx, v in enumerate(val)]
            elif isinstance(val, dict):
                items = [(idx, k, v) for idx, (k, v) in enumerate(val.items())]
            if not items:
                self._render_nodes(node.inverse, frames, out); return
            total = len(items)
            for idx_, key, v in [(it[0], it[1], it[2]) for it in items]:
                bp = {}
                if node.call.block_params:
                    bp[node.call.block_params[0]] = v
                    if len(node.call.block_params) > 1:
                        bp[node.call.block_params[1]] = key if key is not None else idx_
                data = {"index": idx_, "first": idx_ == 0, "last": idx_ == total-1}
                if key is not None: data["key"] = key
                frames.append({"value": v, "block_params": bp, "data": data})
                try: self._render_nodes(node.body, frames, out)
                finally: frames.pop()
            return
        if name == "raw":
            self._render_nodes(node.body, frames, out)
            return
        if name in ("eq","ne","gt","gte","lt","lte","and","or","not"):
            val = self._eval_call(node.call, frames, node.line, node.col, block=node)
            # conditional block helpers
            self._render_nodes(node.body if is_truthy(val, False) else node.inverse, frames, out)
            return
        # generic helper used as block: evaluate and output its value (body ignored); unknown -> error
        val = self._eval_call(node.call, frames, node.line, node.col, block=node)
        out.append(render_value(val))
    # ----- evaluation -----
    def _eval_param(self, param, frames, line, col):
        if isinstance(param, Literal):
            return param.value
        if isinstance(param, Path):
            return self._resolve_path(param.raw, frames, line, col)
        if isinstance(param, SubExpr):
            return self._eval_call(param.call, frames, line, col, block=None)
        return None
    def _eval_call(self, call, frames, line, col, block=None):
        name = _call_name(call)
        if name == "__literal__":
            return call.args[0].value if call.args else None
        # variable expression when no args/hash and name is not a registered helper
        if not call.args and not call.hash and not call.block_params:
            if name in REGISTERED_HELPERS:
                return self._call_helper(name, call, [], frames, line, col)
            # a path (may be nested / this / @root...)
            return self._resolve_path(name, frames, line, col)
        args = [self._eval_param(a, frames, line, col) for a in call.args]
        return self._call_helper(name, call, args, frames, line, col)
    def _call_helper(self, name, call, args, frames, line, col):
        # hashes evaluated lazily for specific helpers? evaluate now except if handled above
        if name in STRING_HELPERS:
            spec = STRING_HELPERS[name]
            pname = spec.get("param", "t")
            if len(args) < 1:
                raise RenderError(f"Helper/Decorator {name} param with name {pname} required but not found", line, col)
            if not isinstance(args[0], str):
                raise RenderError(f"Helper/Decorator {name} param with name {pname} type mismatch for str", line, col)
            text = args[0]
            style = spec.get("style")
            if name == "uppercase":
                return text.upper()
            if name == "level_style":
                return level_style(text)
            return ansi(style, text)
        if name == "color_rgb":
            vals = []
            for idx, pname in enumerate(["r","g","b"]):
                if len(args) <= idx:
                    raise RenderError(f"Helper/Decorator color_rgb param with name {pname} required but not found", line, col)
                v = args[idx]
                if not _is_u64(v):
                    raise RenderError(f"Helper/Decorator color_rgb param with name {pname} type mismatch for u64", line, col)
                vals.append(v)
            if len(args) <= 3:
                raise RenderError("Helper/Decorator color_rgb param with name t required but not found", line, col)
            if not isinstance(args[3], str):
                raise RenderError("Helper/Decorator color_rgb param with name t type mismatch for str", line, col)
            for v in vals:
                if v > 255:
                    raise RustPanic("src/template.rs:38:46", "called `Result::unwrap()` on an `Err` value: TryFromIntError(())")
            return ansi(f"38;2;{vals[0]};{vals[1]};{vals[2]}", args[3])
        if name in ("fixed_size", "min_size"):
            if len(args) < 1:
                raise RenderError(f"Helper/Decorator {name} param with name isize required but not found", line, col)
            if not _is_u64(args[0]):
                raise RenderError(f"Helper/Decorator {name} param with name isize type mismatch for u64", line, col)
            if len(args) < 2:
                raise RenderError(f"Helper/Decorator {name} param with name t required but not found", line, col)
            if not isinstance(args[1], str):
                raise RenderError(f"Helper/Decorator {name} param with name t type mismatch for str", line, col)
            size = args[0]; text = args[1]
            b = text.encode("utf-8")
            if name == "fixed_size":
                if size < len(b):
                    # check char boundary at size
                    if size > 0 and size < len(b) and (b[size] & 0xC0) == 0x80:
                        raise RustPanic("src/template.rs:61:15", "assertion failed: self.is_char_boundary(new_len)")
                    return b[:size].decode("utf-8", "ignore")
                if size > len(b):
                    return " " * (size - len(b)) + text
                return text
            else:
                if len(b) < size:
                    return " " * (size - len(b)) + text
                return text
        if name == "lookup":
            if len(args) < 1: raise RenderError("Helper/Decorator lookup param at index 0 required but not found", line, col)
            if len(args) < 2: raise RenderError("Helper/Decorator lookup param at index 1 required but not found", line, col)
            target, key = args[0], args[1]
            if isinstance(target, list) and isinstance(key, int) and not isinstance(key, bool):
                return target[key] if 0 <= key < len(target) else None
            if isinstance(target, dict) and isinstance(key, str):
                return target.get(key)
            return None
        if name == "log":
            return None
        if name == "len":
            if not call.args:
                raise RenderError("Helper/Decorator len param with name x required but not found", line, col)
            v = args[0] if args else None
            if isinstance(v, str): return len(v.encode("utf-8"))
            if isinstance(v, (list, dict)): return len(v)
            return 0
        if name in ("eq","ne","gt","gte","lt","lte"):
            if len(args) < 1: raise RenderError(f"Helper/Decorator {name} param at index 0 required but not found", line, col)
            if len(args) < 2: raise RenderError(f"Helper/Decorator {name} param at index 1 required but not found", line, col)
            a, b = args[0], args[1]
            if name == "eq": return json_eq(a, b)
            if name == "ne": return not json_eq(a, b)
            cmp = json_cmp(a, b)
            if cmp is None: return False
            return {"gt": cmp > 0, "gte": cmp >= 0, "lt": cmp < 0, "lte": cmp <= 0}[name]
        if name == "and":
            return all(is_truthy(a, False) for a in args)
        if name == "or":
            return any(is_truthy(a, False) for a in args)
        if name == "not":
            if len(args) < 1: raise RenderError("Helper/Decorator not param at index 0 required but not found", line, col)
            return not is_truthy(args[0], False)
        if name in ("if","unless","each","with","raw"):
            return None
        raise RenderError(f"Helper not found {name}", line, col)
    def _resolve_path(self, raw, frames, line, col):
        # parse path
        parent = 0
        rest = raw
        while rest.startswith("../"):
            parent += 1; rest = rest[3:]
        if rest.startswith("./"):
            rest = rest[2:]
        frame_idx = len(frames)-1-parent
        if frame_idx < 0:
            return None
        # @root / @data
        if rest == "@root" or rest.startswith("@root.") or rest.startswith("@root/"):
            segs = _split_path(rest[len("@root"):].lstrip("./"))
            if not segs: return None
            return _navigate(frames[0]["value"], segs, line, col)
        if rest.startswith("@"):
            # block data e.g. @index, @key, @first, @last, @path
            m = re.match(r"@([A-Za-z0-9_-]+)(.*)", rest, re.S)
            if not m: return None
            dname = m.group(1); tail = m.group(2).lstrip("./")
            # search from selected frame down
            for fi in range(frame_idx, -1, -1):
                data = frames[fi].get("data") or {}
                if dname in data:
                    val = data[dname]
                    if tail:
                        return _navigate(val, _split_path(tail), line, col)
                    return val
            return None
        segs = _split_path(rest)
        if not segs:
            return frames[frame_idx]["value"]
        if segs[0] == "this":
            if len(segs) == 1: return frames[frame_idx]["value"]
            return _navigate(frames[frame_idx]["value"], segs[1:], line, col)
        # block params (search from selected frame downwards)
        for fi in range(frame_idx, -1, -1):
            bp = frames[fi].get("block_params") or {}
            if segs[0] in bp:
                val = bp[segs[0]]
                if len(segs) == 1: return val
                return _navigate(val, segs[1:], line, col)
        return _navigate(frames[frame_idx]["value"], segs, line, col)

def _call_name(call):
    return call.name if isinstance(call.name, str) else str(call.name)

def _split_path(rest):
    if rest == "": return []
    segs = []
    i = 0; cur = []
    while i < len(rest):
        c = rest[i]
        if c == "[":
            if cur:
                segs.append("".join(cur)); cur = []
            end = rest.find("]", i)
            if end == -1:
                cur.append(rest[i:]); i = len(rest); break
            segs.append(rest[i+1:end])
            i = end+1
            # skip one separator after ]
            if i < len(rest) and rest[i] in "./":
                i += 1
            continue
        if c in "./":
            if cur:
                segs.append("".join(cur)); cur = []
            i += 1; continue
        cur.append(c); i += 1
    if cur: segs.append("".join(cur))
    return segs

def _navigate(value, segs, line, col):
    cur = value
    for seg in segs:
        if cur is None:
            return None
        if isinstance(cur, dict):
            cur = cur.get(seg)
        elif isinstance(cur, list):
            if re.fullmatch(r"[0-9]+", seg or ""):
                idx = int(seg)
                cur = cur[idx] if idx < len(cur) else None
            else:
                raise RenderError(f"Cannot access array/vector with string index, {seg}", line, col)
        else:
            return None
    return cur

def render_value(v):
    if v is None: return ""
    if isinstance(v, str): return v
    if v is True: return "true"
    if v is False: return "false"
    if isinstance(v, float): return fmt_f64(v)
    if isinstance(v, int): return str(v)
    if isinstance(v, dict): return "[object]"
    if isinstance(v, list): return "[" + ", ".join(render_value(x) for x in v) + "]"
    return str(v)

def is_truthy(v, include_zero):
    if v is None or v is False: return False
    if v is True: return True
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        if include_zero: return True
        return v != 0
    if isinstance(v, str): return len(v) > 0
    if isinstance(v, (list, dict)): return len(v) > 0
    return bool(v)

def json_eq(a, b):
    # type-sensitive: int != float, bool distinct
    if type(a) is bool or type(b) is bool:
        return type(a) is bool and type(b) is bool and a == b
    if a is None or b is None:
        return a is None and b is None
    if isinstance(a, float) or isinstance(b, float):
        return isinstance(a, float) and isinstance(b, float) and a == b
    if isinstance(a, int) or isinstance(b, int):
        return isinstance(a, int) and isinstance(b, int) and a == b
    if isinstance(a, str) or isinstance(b, str):
        return isinstance(a, str) and isinstance(b, str) and a == b
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(json_eq(x, y) for x, y in zip(a, b))
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(json_eq(a[k], b[k]) for k in a)
    return False

def json_cmp(a, b):
    anum = isinstance(a, (int, float)) and not isinstance(a, bool)
    bnum = isinstance(b, (int, float)) and not isinstance(b, bool)
    if anum and bnum:
        return (a > b) - (a < b)
    if isinstance(a, str) and isinstance(b, str):
        return (a > b) - (a < b)
    if isinstance(a, bool) and isinstance(b, bool):
        return (a > b) - (a < b)
    if a is None and b is None:
        return 0
    return None

def _is_u64(v):
    return isinstance(v, int) and not isinstance(v, bool) and 0 <= v <= 2**64-1

def level_style(text):
    t = text.strip().lower()
    if t == "info": code = "1;32"
    elif t == "debug": code = "1;34"
    elif t == "trace": code = "1;36"
    elif t in ("warn", "warning"): code = "1;33"
    elif t in ("error", "err"): code = "1;31"
    else: code = "1;35"
    return ansi(code, text)

