def typename(v):
    if v is NIL: return "nil"
    if isinstance(v,bool): return "boolean"
    if isinstance(v,(int,float)): return "number"
    if isinstance(v,bytes): return "string"
    if isinstance(v,LuaTable): return "table"
    if isinstance(v,(LuaFunction,BuiltinFunction)): return "function"
    if isinstance(v,LuaCoroutine): return "thread"
    return "userdata"

def lua_eq(a,b):
    if a is NIL or b is NIL: return a is NIL and b is NIL
    anum=isinstance(a,(int,float)) and not isinstance(a,bool)
    bnum=isinstance(b,(int,float)) and not isinstance(b,bool)
    if anum and bnum: return a==b
    if type(a)!=type(b):
        # LuaTable/function subtypes belong same categories but identity below
        if isinstance(a,(LuaFunction,BuiltinFunction)) and isinstance(b,(LuaFunction,BuiltinFunction)):
            return a is b
        return False
    if isinstance(a,(LuaTable,LuaFunction,BuiltinFunction,LuaFile,LuaCoroutine)):
        return a is b
    return a==b

