                if self.accept(","): step=self.parse_expr()
                self.expect("do"); body=self.parse_block({"end"}); self.expect("end")
                return N("fornum",t.line,name=name1,start=start,limit=limit,step=step,body=body)
            names=[name1]
            while self.accept(","): names.append(self.expect_name().val)
            self.expect("in"); exprs=self.parse_exprlist(); self.expect("do"); body=self.parse_block({"end"}); self.expect("end")
            return N("forgen",t.line,names=names,exprs=exprs,body=body)
        if t.typ=="local":
            self.advance()
            if self.check("function"):
                self.advance(); nm=self.expect_name()
                fn=self.parse_function_body(t.line)
                return N("localfunc",t.line,name=nm.val,func=fn)
            names=[]
            while True:
                names.append(self.expect_name().val)
                if self.accept("<"):
                    self.expect_name(); self.expect(">")
                if not self.accept(","): break
            exprs=[]
            if self.accept("="): exprs=self.parse_exprlist()
            return N("local",t.line,names=names,exprs=exprs)
        if t.typ=="function":
            self.advance(); nm=self.expect_name(); target=N("var",nm.line,name=nm.val); is_method=False
            while self.accept("."):
                f=self.expect_name(); target=N("field",f.line,obj=target,name=f.val)
            if self.accept(":"):
                f=self.expect_name(); target=N("field",f.line,obj=target,name=f.val); is_method=True
            fn=self.parse_function_body(t.line,method=is_method)
            return N("assign",t.line,targets=[target],exprs=[fn])
        if t.typ=="break": self.advance(); return N("break",t.line)
        if t.typ=="goto": self.advance(); nm=self.expect_name(); return N("goto",t.line,name=nm.val)
        if t.typ=="::":
            self.advance(); nm=self.expect_name(); self.expect("::"); return N("label",t.line,name=nm.val)
        # assignment or call statement
        expr=self.parse_suffixed_expr()
        if self.check(",") or self.check("="):
            targets=[expr]
            while self.accept(","):
                targets.append(self.parse_suffixed_expr())
            self.expect("="); exprs=self.parse_exprlist()
            return N("assign",t.line,targets=targets,exprs=exprs)
        if expr["k"] not in ("call","mcall"):
            # Lua expects assignment/call
            self.err(f"syntax error near {self.tok().near()}")
        return N("callstmt",t.line,expr=expr)
    def parse_function_body(self,line,method=False):
        self.expect("("); params=[]; vararg=False
        if method: params.append("self")
        if not self.check(")"):
            while True:
                if self.check("..."): self.advance(); vararg=True; break
                params.append(self.expect_name().val)
                if not self.accept(","): break
        self.expect(")")
        self.func_vararg.append(vararg)
        body=self.parse_block({"end"})
        self.func_vararg.pop()
        self.expect("end")
        return N("function",line,params=params,vararg=vararg,body=body)
    def parse_exprlist(self):
        lst=[self.parse_expr()]
        while self.accept(","): lst.append(self.parse_expr())
        return lst
    # expression precedence
    BINPRI={"or":1,"and":2,"<":3,">":3,"<=":3,">=":3,"~=":3,"==":3,"|":4,"~":5,"&":6,"<<":7,">>":7,"..":8,"+":9,"-":9,"*":10,"/":10,"//":10,"%":10,"^":12}
    def parse_expr(self,minp=0):
        t=self.tok()
        if t.typ in ("not","-","#","~"):
            op=self.advance(); operand=self.parse_expr(11)
            left=N("unop",op.line,op=op.typ,expr=operand)
        else:
            left=self.parse_simple_expr()
        while True:
            op=self.tok().typ
            pri=self.BINPRI.get(op)
            if pri is None or pri<minp: break
            opt=self.advance()
            # right associative for .. and ^
            nextmin=pri if op in ("..","^") else pri+1
            right=self.parse_expr(nextmin)
            left=N("binop",opt.line,op=op,left=left,right=right)
        return left
    def parse_simple_expr(self):
        t=self.tok()
        if t.typ=="NUMBER": self.advance(); return N("num",t.line,value=t.val)
        if t.typ=="STRING": self.advance(); return N("str",t.line,value=t.val)
        if t.typ=="nil": self.advance(); return N("nil",t.line)
        if t.typ=="true": self.advance(); return N("bool",t.line,value=True)
        if t.typ=="false": self.advance(); return N("bool",t.line,value=False)
        if t.typ=="...":
            if not self.func_vararg[-1]: self.err("cannot use '...' outside a vararg function near '...'",t)
            self.advance(); return N("vararg",t.line)
        if t.typ=="function":
            self.advance(); return self.parse_function_body(t.line)
        if t.typ=="{":
            return self.parse_table()
        if t.typ=="NAME" or t.typ=="(":
            return self.parse_suffixed_expr()
        self.err(f"unexpected symbol near {t.near()}",t)
    def parse_suffixed_expr(self):
        t=self.tok()
        if t.typ=="NAME":
            self.advance(); e=N("var",t.line,name=t.val)
        elif t.typ=="(":
            self.advance(); inner=self.parse_expr(); self.expect(")"); e=N("paren",t.line,expr=inner)
        else:
            self.err(f"unexpected symbol near {t.near()}",t)
        while True:
            tt=self.tok()
            if tt.typ==".":
                self.advance(); nm=self.expect_name(); e=N("field",tt.line,obj=e,name=nm.val); continue
            if tt.typ=="[":
                self.advance(); key=self.parse_expr(); self.expect("]"); e=N("index",tt.line,obj=e,key=key); continue
            if tt.typ==":":
                self.advance(); nm=self.expect_name(); args=self.parse_call_args(); e=N("mcall",tt.line,obj=e,name=nm.val,args=args); continue
            if tt.typ=="(" or tt.typ=="STRING" or tt.typ=="{":
                args=self.parse_call_args(); e=N("call",tt.line,fn=e,args=args); continue
            break
        return e
    def parse_call_args(self):
        t=self.tok()
        if t.typ=="(":
            self.advance(); args=[]
            if not self.check(")"): args=self.parse_exprlist()
            self.expect(")"); return args
        if t.typ=="STRING": self.advance(); return [N("str",t.line,value=t.val)]
        if t.typ=="{": return [self.parse_table()]
        self.err(f"expected arguments near {t.near()}",t)
    def parse_table(self):
        t=self.expect("{"); fields=[]
        while not self.check("}"):
            if self.check("["):
                self.advance(); k=self.parse_expr(); self.expect("]"); self.expect("="); v=self.parse_expr(); fields.append(("key",k,v))
            elif self.tok().typ=="NAME" and self.toks[self.i+1].typ=="=":
                nm=self.advance(); self.advance(); v=self.parse_expr(); fields.append(("name",nm.val,v))
            else:
                fields.append(("pos",self.parse_expr()))
            if self.check(",") or self.check(";"): self.advance(); continue
            break
        self.expect("}")
        return N("table",t.line,fields=fields)

