class LuaSyntaxError(Exception):
    def __init__(self, msg, line, incomplete=False, chunk=""):
        super().__init__(msg)
        self.msg=msg; self.line=line; self.incomplete=incomplete; self.chunk=chunk
    def debug(self):
        m = f"{self.chunk}:{self.line}: {self.msg}"
        return f"SyntaxError {{ message: {_dbg(m)}, incomplete_input: {str(self.incomplete).lower()} }}"

class LuaRuntimeErr(Exception):
    def __init__(self, value, trace_lines):
        super().__init__("lua runtime")
        self.value=value; self.trace_lines=trace_lines
    def message_bytes(self, interp):
        if isinstance(self.value, bytes): return self.value
        return interp.tostring_bytes(self.value)

def _dbg(s):
    out=['"']
    for ch in s:
        if ch=='"': out.append('\\"')
        elif ch=='\\': out.append('\\\\')
        elif ch=='\n': out.append('\\n')
        elif ch=='\r': out.append('\\r')
        elif ch=='\t': out.append('\\t')
        elif ord(ch)<0x20 or ord(ch)==0x7f: out.append('\\u{%x}'%ord(ch))
        else: out.append(ch)
    out.append('"'); return "".join(out)

class ReturnExc(Exception):
    def __init__(self, vals): self.vals=vals
class BreakExc(Exception): pass
class GotoExc(Exception):
    def __init__(self,name): self.name=name

class Cell:
    __slots__=("value",)
    def __init__(self,v=NIL): self.value=v

class Scope:
    __slots__=("parent","vars","function_id")
    def __init__(self,parent=None,function_id=0):
        self.parent=parent; self.vars={}; self.function_id=function_id
    def find(self,name):
        s=self
        while s is not None:
            if name in s.vars: return s.vars[name], s
            s=s.parent
        return None, None
    def declare(self,name,v=NIL):
        c=Cell(v); self.vars[name]=c; return c

class LuaTable:
    _counter=0
    def __init__(self):
        LuaTable._counter+=1; self._id=LuaTable._counter
        self.map={}  # normkey -> (origkey, value)
        self.metatable=None
    def _norm(self,k):
        if isinstance(k,bool): return ("b",k)
        if isinstance(k,int): return ("n",k)
        if isinstance(k,float):
            if math.isnan(k): return ("nan",)
            if k.is_integer() and -(2**63) <= k <= 2**63-1: return ("n",int(k))
            return ("f",k)
        if isinstance(k,bytes): return ("s",k)
        if k is NIL: return ("nil",)
        return ("o",id(k))
    def get(self,k):
        if k is NIL: return NIL
        ent=self.map.get(self._norm(k))
        return ent[1] if ent else NIL
    def set(self,k,v):
        n=self._norm(k)
        if v is NIL:
            self.map.pop(n,None)
        else:
            # numeric float integral original key should be int
            orig=k
            if isinstance(k,float) and k.is_integer() and -(2**63)<=k<=2**63-1: orig=int(k)
            self.map[n]=(orig,v)
    def rawlen(self):
        i=1
        while self.get(i) is not NIL: i+=1
        return i-1
    def items(self):
        return list(self.map.values())
    def next_key(self,k):
        keys=[orig for orig,_ in self.map.values()]
        if k is NIL:
            if not keys: return NIL
            kk=keys[0]; return kk
        for idx,orig in enumerate(keys):
            if lua_eq(orig,k):
                return keys[idx+1] if idx+1<len(keys) else NIL
        return _NEXT_INVALID
class _NextInvalid: pass
_NEXT_INVALID=_NextInvalid()

class LuaFunction:
    def __init__(self, params, vararg, body, scope, env_cell, chunk, line):
        self.params=params; self.vararg=vararg; self.body=body; self.scope=scope; self.env_cell=env_cell; self.chunk=chunk; self.line=line
class BuiltinFunction:
    def __init__(self, short, full, fn):
        self.short=short; self.full=full; self.fn=fn
class LuaFile:
    def __init__(self, fp, name="file", mode="r"):
        self.fp=fp; self.name=name; self.mode=mode; self.closed=False
class LuaCoroutine:
    def __init__(self, fn): self.fn=fn; self.status="suspended"

def typename(v):
    if v is NIL: return "nil"
    if isinstance(v,bool): return "boolean"
    if isinstance(v,(int,float)): return "number"
    if isinstance(v,bytes): return "string"
    if isinstance(v,LuaTable): return "table"
    if isinstance(v,(LuaFunction,BuiltinFunction)): return "function"
    if isinstance(v,LuaCoroutine): return "thread"
    return "userdata"

def lua_eq(a,b):
    if a is NIL or b is NIL: return a is NIL and b is NIL
    anum=isinstance(a,(int,float)) and not isinstance(a,bool)
    bnum=isinstance(b,(int,float)) and not isinstance(b,bool)
    if anum and bnum: return a==b
    if type(a)!=type(b):
        # LuaTable/function subtypes belong same categories but identity below
        if isinstance(a,(LuaFunction,BuiltinFunction)) and isinstance(b,(LuaFunction,BuiltinFunction)):
            return a is b
        return False
    if isinstance(a,(LuaTable,LuaFunction,BuiltinFunction,LuaFile,LuaCoroutine)):
        return a is b
    return a==b

def truthy(v): return not (v is NIL or v is False)

# ---------------- Lexer ----------------
KEYWORDS={"and","break","do","else","elseif","end","false","for","function","goto","if","in","local","nil","not","or","repeat","return","then","true","until","while"}
class Tok:
    __slots__=("typ","val","line","text")
    def __init__(self,typ,val,line,text=None): self.typ=typ; self.val=val; self.line=line; self.text=text if text is not None else typ
    def near(self):
        if self.typ=="EOF": return "<eof>"
        t=self.text
        if isinstance(t,bytes): t=t.decode('utf-8','replace')
        return f"'{t}'"

class Lexer:
    def __init__(self,data,chunk):
        if isinstance(data,str): data=data.encode('utf-8','surrogateescape')
        self.s=data; self.i=0; self.line=1; self.chunk=chunk
    def err(self,msg,line=None,incomplete=False):
        raise LuaSyntaxError(msg, self.line if line is None else line, incomplete, self.chunk)
    def peekb(self,off=0):
        j=self.i+off
        return self.s[j] if j<len(self.s) else -1
    def tokens(self):
        out=[]
        while True:
            t=self.next_token(); out.append(t)
            if t.typ=="EOF": return out
    def _long_bracket_level(self,pos):
        # s[pos]=='['; return level or -1
        j=pos+1; lvl=0
        while j<len(self.s) and self.s[j:j+1]==b'=':
            lvl+=1; j+=1
        if j<len(self.s) and self.s[j:j+1]==b'[':
            return lvl, j+1
        return -1, pos+1
    def _read_long(self,pos,in_comment=False):
        lvl,start=self._long_bracket_level(pos)
        # self.i at '['
        start_line=self.line
        self.i=start
        # skip first newline
        if self.peekb()==10:
            self.i+=1; self.line+=1
        elif self.peekb()==13:
            # \r or \r\n as first newline
            self.i+=1
            if self.peekb()==10: self.i+=1
            self.line+=1
        close=b']'+b'='*lvl+b']'
        end=self.s.find(close,self.i)
        if end==-1:
            self.err("unfinished long string" if not in_comment else "unfinished long comment",start_line,True)
        content=self.s[self.i:end]
        self.line += content.count(b'\n')
        self.i=end+len(close)
        return content
    def _skip(self):
        while self.i<len(self.s):
            c=self.s[self.i]
            if c in b' \t\x0b\x0c\r':
                self.i+=1; continue
            if c==10:
                self.i+=1; self.line+=1; continue
            if self.s[self.i:self.i+2]==b'--':
                nxt=self.i+2
                if nxt<len(self.s) and self.s[nxt:nxt+1]==b'[':
                    lvl,_=self._long_bracket_level(nxt)
                    if lvl>=0:
                        self.i=nxt; self._read_long(nxt,True); continue
                # line comment
                j=self.s.find(b'\n',self.i)
                if j==-1: self.i=len(self.s)
                else: self.i=j
                continue
            break
    def next_token(self):
        self._skip()
        start_line=self.line
        if self.i>=len(self.s): return Tok("EOF",None,start_line,"<eof>")
        c=self.s[self.i]
        ch=chr(c)
        # name
        if ch=='_' or ch.isalpha():
            j=self.i
            while j<len(self.s):
                d=chr(self.s[j])
                if d=='_' or d.isalnum(): j+=1
                else: break
            name=self.s[self.i:j].decode('ascii','replace'); self.i=j
            if name in KEYWORDS: return Tok(name,name,start_line,name)
            return Tok("NAME",name,start_line,name)
        # numbers
        if ch.isdigit() or (ch=='.' and self.peekb(1)>=48 and self.peekb(1)<=57):
            return self._number(start_line)
        if ch in '"\'':
            return Tok("STRING",self._short_string(),start_line,"string")
        if ch=='[':
            lvl,_=self._long_bracket_level(self.i)
            if lvl>=0:
                return Tok("STRING",self._read_long(self.i),start_line,"string")
            self.i+=1; return Tok("[","[",start_line,"[")
        # multi-char punctuation
        three=self.s[self.i:self.i+3]
        if three==b'...':
            self.i+=3; return Tok("...","...",start_line,"...")
        two=self.s[self.i:self.i+2]
        for p in [b'..',b'==',b'~=',b'<=',b'>=',b'//',b'<<',b'>>',b'::']:
            if two==p:
                t=p.decode(); self.i+=2; return Tok(t,t,start_line,t)
        self.i+=1
        return Tok(ch,ch,start_line,ch)
    def _short_string(self):
        q=self.s[self.i]; self.i+=1; out=bytearray()
        while self.i<len(self.s):
            c=self.s[self.i]; self.i+=1
            if c==q:
                return bytes(out)
            if c==10 or c==13:
                self.err("unfinished string",incomplete=True)
            if c==92: # \
                if self.i>=len(self.s): break
                e=self.s[self.i]; self.i+=1
                mp={97:7,98:8,102:12,110:10,114:13,116:9,118:11,92:92,34:34,39:39}
                if e in mp: out.append(mp[e]); continue
                if e==10: out.append(10); self.line+=1; continue
                if e==13:
                    if self.peekb()==10: self.i+=1
                    out.append(10); self.line+=1; continue
                if e==ord('x'):
                    hx=self.s[self.i:self.i+2]
                    if len(hx)<2 or not all(chr(x) in '0123456789abcdefABCDEF' for x in hx): self.err("hexadecimal digit expected")
                    out.append(int(hx,16)); self.i+=2; continue
                if e==ord('u'):
                    if self.peekb()!=ord('{'): self.err("missing '{' in \\u{xxxx}")
                    end=self.s.find(b'}',self.i)
                    if end==-1: self.err("missing '}' in \\u{xxxx}")
                    try: cp=int(self.s[self.i+1:end],16)
                    except Exception: self.err("invalid UTF-8 codepoint")
                    out.extend(chr(cp).encode('utf-8','replace')); self.i=end+1; continue
                if e==ord('z'):
                    while self.i<len(self.s) and chr(self.s[self.i]) in ' \t\r\n\x0b\x0c':
                        if self.s[self.i]==10: self.line+=1
                        self.i+=1
                    continue
                if 48<=e<=57:
                    digits=bytes([e]); count=1
                    while count<3 and self.i<len(self.s) and 48<=self.s[self.i]<=57:
                        digits+=bytes([self.s[self.i]]); self.i+=1; count+=1
                    v=int(digits)
                    if v>255: self.err("decimal escape too large")
                    out.append(v); continue
                self.err("invalid escape sequence")
            out.append(c)
        self.err("unfinished string",incomplete=True)
    def _number(self,start_line):
        s=self.s; j=self.i
        is_float=False
        if s[j:j+2] in (b'0x',b'0X'):
            j+=2; start_hex=j; has_dot=False
            while j<len(s) and (chr(s[j]) in '0123456789abcdefABCDEF.' ):
                if s[j:j+1]==b'.': has_dot=True
                j+=1
            if j<len(s) and s[j:j+1] in (b'p',b'P'):
                is_float=True; j+=1
                if j<len(s) and s[j:j+1] in (b'+',b'-'): j+=1
                while j<len(s) and chr(s[j]).isdigit(): j+=1
            text=s[self.i:j].decode('ascii')
            self.i=j
            try:
                if has_dot or is_float:
                    return Tok("NUMBER",float.fromhex(text),start_line,text)
                return Tok("NUMBER",wrap_i64(int(text,16)),start_line,text)
            except Exception:
                self.err("malformed number",start_line)
        while j<len(s) and chr(s[j]).isdigit(): j+=1
        if j<len(s) and s[j:j+1]==b'.' and s[j:j+2]!=b'..':
            is_float=True; j+=1
            while j<len(s) and chr(s[j]).isdigit(): j+=1
        if j<len(s) and s[j:j+1] in (b'e',b'E'):
            is_float=True; j+=1
            if j<len(s) and s[j:j+1] in (b'+',b'-'): j+=1
            while j<len(s) and chr(s[j]).isdigit(): j+=1
        text=s[self.i:j].decode('ascii'); self.i=j
        try:
            if is_float: return Tok("NUMBER",float(text),start_line,text)
            return Tok("NUMBER",wrap_i64(int(text)),start_line,text)
        except Exception:
            self.err("malformed number",start_line)

# ---------------- Parser (AST nodes as dicts) ----------------
def N(kind,line,**kw):
    d={"k":kind,"line":line}; d.update(kw); return d

class Parser:
    def __init__(self,toks,chunk):
        self.toks=toks; self.i=0; self.chunk=chunk; self.func_vararg=[True]
    def tok(self): return self.toks[min(self.i,len(self.toks)-1)]
    def advance(self):
        t=self.tok();
        if self.i<len(self.toks)-1: self.i+=1
        return t
    def check(self,typ): return self.tok().typ==typ
    def accept(self,typ):
        if self.check(typ): return self.advance()
        return None
    def err(self,msg,tok=None):
        t=tok or self.tok(); raise LuaSyntaxError(msg,t.line,t.typ=="EOF",self.chunk)
    def expect(self,typ):
        if not self.check(typ):
            t=self.tok(); self.err(f"'{typ}' expected near {t.near()}",t)
        return self.advance()
    def expect_name(self):
        if self.tok().typ!="NAME":
            t=self.tok(); self.err(f"<name> expected near {t.near()}",t)
        return self.advance()
    def parse(self):
        body=self.parse_block(set())
        if self.tok().typ!="EOF":
            t=self.tok(); self.err(f"<eof> expected near {t.near()}",t)
        return body
    def parse_block(self,stop):
        nodes=[]
        while self.tok().typ not in stop and self.tok().typ!="EOF":
            if self.check("return"):
                nodes.append(self.parse_return())
                # return must be last in block
                if self.tok().typ not in stop and self.tok().typ!="EOF":
                    t=self.tok(); self.err(f"<eof> expected near {t.near()}",t)
                break
            st=self.parse_statement()
            if st is not None: nodes.append(st)
        return nodes
    def parse_return(self):
        t=self.expect("return")
        exprs=[]
        if self.tok().typ not in ("EOF","end","else","elseif","until",";"):
            exprs=self.parse_exprlist()
        self.accept(";")
        return N("return",t.line,exprs=exprs)
    def parse_statement(self):
        t=self.tok()
        if t.typ==";": self.advance(); return None
        if t.typ=="do":
            self.advance(); body=self.parse_block({"end"}); self.expect("end"); return N("do",t.line,body=body)
        if t.typ=="while":
            self.advance(); cond=self.parse_expr(); self.expect("do"); body=self.parse_block({"end"}); self.expect("end"); return N("while",t.line,cond=cond,body=body)
        if t.typ=="repeat":
            self.advance(); body=self.parse_block({"until"}); self.expect("until"); cond=self.parse_expr(); return N("repeat",t.line,body=body,cond=cond)
        if t.typ=="if":
            self.advance(); branches=[]
            cond=self.parse_expr(); self.expect("then"); branches.append((cond,self.parse_block({"else","elseif","end"})))
            elseb=None
            while self.check("elseif"):
                self.advance(); c=self.parse_expr(); self.expect("then"); branches.append((c,self.parse_block({"else","elseif","end"})))
            if self.check("else"):
                self.advance(); elseb=self.parse_block({"end"})
            self.expect("end"); return N("if",t.line,branches=branches,elsebody=elseb)
        if t.typ=="for":
            self.advance(); name1=self.expect_name().val
            if self.accept("="):
                start=self.parse_expr(); self.expect(","); limit=self.parse_expr(); step=None
                if self.accept(","): step=self.parse_expr()
                self.expect("do"); body=self.parse_block({"end"}); self.expect("end")
                return N("fornum",t.line,name=name1,start=start,limit=limit,step=step,body=body)
            names=[name1]
            while self.accept(","): names.append(self.expect_name().val)
            self.expect("in"); exprs=self.parse_exprlist(); self.expect("do"); body=self.parse_block({"end"}); self.expect("end")
            return N("forgen",t.line,names=names,exprs=exprs,body=body)
        if t.typ=="local":
            self.advance()
            if self.check("function"):
                self.advance(); nm=self.expect_name()
                fn=self.parse_function_body(t.line)
                return N("localfunc",t.line,name=nm.val,func=fn)
            names=[]
            while True:
                names.append(self.expect_name().val)
                if self.accept("<"):
                    self.expect_name(); self.expect(">")
                if not self.accept(","): break
            exprs=[]
            if self.accept("="): exprs=self.parse_exprlist()
            return N("local",t.line,names=names,exprs=exprs)
        if t.typ=="function":
            self.advance(); nm=self.expect_name(); target=N("var",nm.line,name=nm.val); is_method=False
            while self.accept("."):
                f=self.expect_name(); target=N("field",f.line,obj=target,name=f.val)
            if self.accept(":"):
                f=self.expect_name(); target=N("field",f.line,obj=target,name=f.val); is_method=True
            fn=self.parse_function_body(t.line,method=is_method)
            return N("assign",t.line,targets=[target],exprs=[fn])
        if t.typ=="break": self.advance(); return N("break",t.line)
        if t.typ=="goto": self.advance(); nm=self.expect_name(); return N("goto",t.line,name=nm.val)
        if t.typ=="::":
            self.advance(); nm=self.expect_name(); self.expect("::"); return N("label",t.line,name=nm.val)
        # assignment or call statement
        expr=self.parse_suffixed_expr()
        if self.check(",") or self.check("="):
            targets=[expr]
            while self.accept(","):
                targets.append(self.parse_suffixed_expr())
            self.expect("="); exprs=self.parse_exprlist()
            return N("assign",t.line,targets=targets,exprs=exprs)
        if expr["k"] not in ("call","mcall"):
            # Lua expects assignment/call
            self.err(f"syntax error near {self.tok().near()}")
        return N("callstmt",t.line,expr=expr)
    def parse_function_body(self,line,method=False):
        self.expect("("); params=[]; vararg=False
        if method: params.append("self")
        if not self.check(")"):
            while True:
                if self.check("..."): self.advance(); vararg=True; break
                params.append(self.expect_name().val)
                if not self.accept(","): break
        self.expect(")")
        self.func_vararg.append(vararg)
        body=self.parse_block({"end"})
        self.func_vararg.pop()
        self.expect("end")
        return N("function",line,params=params,vararg=vararg,body=body)
    def parse_exprlist(self):
        lst=[self.parse_expr()]
        while self.accept(","): lst.append(self.parse_expr())
        return lst
    # expression precedence
    BINPRI={"or":1,"and":2,"<":3,">":3,"<=":3,">=":3,"~=":3,"==":3,"|":4,"~":5,"&":6,"<<":7,">>":7,"..":8,"+":9,"-":9,"*":10,"/":10,"//":10,"%":10,"^":12}
    def parse_expr(self,minp=0):
        t=self.tok()
        if t.typ in ("not","-","#","~"):
            op=self.advance(); operand=self.parse_expr(11)
            left=N("unop",op.line,op=op.typ,expr=operand)
        else:
            left=self.parse_simple_expr()
        while True:
            op=self.tok().typ
            pri=self.BINPRI.get(op)
            if pri is None or pri<minp: break
            opt=self.advance()
            # right associative for .. and ^
            nextmin=pri if op in ("..","^") else pri+1
            right=self.parse_expr(nextmin)
            left=N("binop",opt.line,op=op,left=left,right=right)
        return left
    def parse_simple_expr(self):
        t=self.tok()
        if t.typ=="NUMBER": self.advance(); return N("num",t.line,value=t.val)
        if t.typ=="STRING": self.advance(); return N("str",t.line,value=t.val)
        if t.typ=="nil": self.advance(); return N("nil",t.line)
        if t.typ=="true": self.advance(); return N("bool",t.line,value=True)
        if t.typ=="false": self.advance(); return N("bool",t.line,value=False)
        if t.typ=="...":
            if not self.func_vararg[-1]: self.err("cannot use '...' outside a vararg function near '...'",t)
            self.advance(); return N("vararg",t.line)
        if t.typ=="function":
            self.advance(); return self.parse_function_body(t.line)
        if t.typ=="{":
            return self.parse_table()
        if t.typ=="NAME" or t.typ=="(":
            return self.parse_suffixed_expr()
        self.err(f"unexpected symbol near {t.near()}",t)
    def parse_suffixed_expr(self):
        t=self.tok()
        if t.typ=="NAME":
            self.advance(); e=N("var",t.line,name=t.val)
        elif t.typ=="(":
            self.advance(); inner=self.parse_expr(); self.expect(")"); e=N("paren",t.line,expr=inner)
        else:
            self.err(f"unexpected symbol near {t.near()}",t)
        while True:
            tt=self.tok()
            if tt.typ==".":
                self.advance(); nm=self.expect_name(); e=N("field",tt.line,obj=e,name=nm.val); continue
            if tt.typ=="[":
                self.advance(); key=self.parse_expr(); self.expect("]"); e=N("index",tt.line,obj=e,key=key); continue
            if tt.typ==":":
                self.advance(); nm=self.expect_name(); args=self.parse_call_args(); e=N("mcall",tt.line,obj=e,name=nm.val,args=args); continue
            if tt.typ=="(" or tt.typ=="STRING" or tt.typ=="{":
                args=self.parse_call_args(); e=N("call",tt.line,fn=e,args=args); continue
            break
        return e
    def parse_call_args(self):
        t=self.tok()
        if t.typ=="(":
            self.advance(); args=[]
            if not self.check(")"): args=self.parse_exprlist()
            self.expect(")"); return args
