        if both_num:
            if op=="<": return l<r
            if op==">": return l>r
            if op=="<=": return l<=r
            return l>=r
        if isinstance(l,bytes) and isinstance(r,bytes):
            if op=="<": return l<r
            if op==">": return l>r
            if op=="<=": return l<=r
            return l>=r
        if type(l)==type(r) or (isinstance(l,LuaTable) and isinstance(r,LuaTable)):
            mmname=b"__lt" if op in ("<",">") else b"__le"
            ml=self.metamethod(l,mmname); mr=self.metamethod(r,mmname)
