def arith(op,a,b,interp,node):
    both_int=isinstance(a,int) and isinstance(b,int)
    if op=="/": return float(a)/float(b) if float(b)!=0 else (math.inf if a>0 else (-math.inf if a<0 else math.nan))
    if op=="^":
        try: return float(a)**float(b)
        except OverflowError: return math.inf
        except Exception: return math.nan
    if op=="//":
        if both_int:
            if b==0: interp.raise_err(b"attempt to divide by zero",pseudo=["[C]: in metamethod 'idiv'"])
            return wrap_i64(a//b)
        fb=float(b)
        if fb==0:
            fa=float(a); return math.inf if fa>0 else (-math.inf if fa<0 else math.nan)
        return math.floor(float(a)/fb)
    if op=="%":
        if both_int:
            if b==0: interp.raise_err(b"attempt to perform 'n%0'",pseudo=["[C]: in metamethod 'mod'"])
            return wrap_i64(a - (a//b)*b)
        fb=float(b)
        if fb==0: return math.nan
        fa=float(a); return fa - math.floor(fa/fb)*fb
    if both_int:
        if op=="+": return wrap_i64(a+b)
        if op=="-": return wrap_i64(a-b)
        if op=="*": return wrap_i64(a*b)
    fa=float(a); fb=float(b)
    if op=="+": return fa+fb
    if op=="-": return fa-fb
    if op=="*": return fa*fb
    return math.nan

def bitwise(op,a,b):
    if op=="&": return wrap_i64(a & b)
    if op=="|": return wrap_i64(a | b)
    if op=="~": return wrap_i64(a ^ b)
    if op=="<<":
        if b<0: return bitwise(">>",a,-b)
        if b>=64: return 0
        return wrap_i64(a << b)
    if op==">>":
        if b<0: return bitwise("<<",a,-b)
        if b>=64: return -1 if a<0 else 0
        return wrap_i64(a >> b)

