# ---------------- number / string conversions ----------------

def num_to_string(v):
    if isinstance(v,int) and not isinstance(v,bool): return str(v).encode()
    x=float(v)
    if math.isnan(x): return b"nan"
    if math.isinf(x): return b"inf" if x>0 else b"-inf"
    s="%.14g"%x
    if not re.search(r"[.eEnN]",s): s+=".0"
    return s.encode()

def str_to_number(b):
    if not isinstance(b,bytes): return None
    try: s=b.decode('utf-8')
    except Exception:
        try: s=b.decode('latin1')
        except Exception: return None
    s=s.strip()
    if not s: return None
    # sign
    try:
        if re.fullmatch(r"[+-]?0[xX][0-9a-fA-F]+",s):
            return wrap_i64(int(s,16))
        if re.fullmatch(r"[+-]?[0-9]+",s):
            return wrap_i64(int(s))
        if re.fullmatch(r"[+-]?0[xX][0-9a-fA-F]*\.?[0-9a-fA-F]*([pP][+-]?[0-9]+)?",s) and ("." in s or "p" in s.lower()):
            return float.fromhex(s)
        if s.lower() in ("inf","+inf","infinity","+infinity"): return math.inf
        if s.lower() in ("-inf","-infinity"): return -math.inf
        if s.lower()=="nan": return math.nan
        f=float(s); return f
    except Exception:
        return None

def to_number(v):
    if isinstance(v,(int,float)) and not isinstance(v,bool): return v
    if isinstance(v,bytes): return str_to_number(v)
    return None

def to_integer(v):
    n=to_number(v)
    if n is None: return None
    if isinstance(n,int): return n
    if isinstance(n,float) and n.is_integer() and -(2**63)<=n<=2**63-1: return int(n)
    return None

class CallFrame:
    __slots__=("kind","chunk","name","namekind","line","defline","fid","env_cell","varargs","func")
    def __init__(self,kind,chunk,name=None,namekind=None,line=1,defline=1,fid=0,env_cell=None,varargs=None,func=None):
        self.kind=kind; self.chunk=chunk; self.name=name; self.namekind=namekind; self.line=line; self.defline=defline; self.fid=fid; self.env_cell=env_cell; self.varargs=varargs or []; self.func=func

class Interp:
    def __init__(self, output_fn=None):
        self.output_fn=output_fn or (lambda data: write_stdout(data))
        self.globals=LuaTable()
        self.global_env_cell=Cell(self.globals)
        self.frames=[]
        self._fid=0
        self.string_mt=LuaTable()
        self._next_addr=0x55b85f900000
        self._addrs={}
        build_libs(self)
        # string metatable __index = string table
        self.string_mt.set(b"__index", self.globals.get(b"string"))
    def addr(self,obj):
        k=id(obj)
        if k not in self._addrs:
            self._next_addr += 0x2560
            self._addrs[k]=self._next_addr
        return self._addrs[k]
    # ---------- errors ----------
    def trace_snapshot(self,pseudo=None):
        lines=[]
        if pseudo: lines.extend(pseudo)
        for fr in reversed(self.frames):
            if fr.kind=="C":
                if fr.name: lines.append(f"[C]: in function '{fr.name}'")
                else: lines.append("[C]: in ?")
            elif fr.kind=="main":
                lines.append(f"{fr.chunk}:{fr.line}: in main chunk")
            else:
                if fr.name:
                    kind=fr.namekind or "function"
                    lines.append(f"{fr.chunk}:{fr.line}: in {kind} '{fr.name}'")
                else:
                    lines.append(f"{fr.chunk}:{fr.line}: in function <{fr.chunk}:{fr.defline}>")
        return lines
    def raise_err(self,message_bytes,pseudo=None,with_location=True):
        fr=self.frames[-1] if self.frames else None
        if with_location and fr is not None:
            loc=f"{fr.chunk}:{fr.line}: ".encode()
            msg=loc+message_bytes
        else:
            msg=message_bytes
        raise LuaRuntimeErr(msg,self.trace_snapshot(pseudo))
    def raise_value(self,value,pseudo=None):
        raise LuaRuntimeErr(value,self.trace_snapshot(pseudo))
    def arg_error(self,callinfo,idx,msg):
        pseudo=["[C]: in ?"]
        name=callinfo.get("short","?")
        fr=self.frames[-1] if self.frames else None
        # frames currently inside builtin: snapshot includes its C frame after pseudo
        self.raise_err(f"bad argument #{idx} to '{name}' ({msg})".encode(),pseudo=pseudo)
    def type_error_expected(self,callinfo,idx,expected,v):
        got="no value" if v is _NOVALUE else typename(v)
        self.arg_error(callinfo,idx,f"{expected} expected, got {got}")
    # ---------- coercions for builtins ----------
    def check_string(self,args,idx,callinfo):
        if idx>len(args): self.type_error_expected(callinfo,idx,"string",_NOVALUE)
        v=args[idx-1]
        if isinstance(v,bytes): return v
        if isinstance(v,(int,float)) and not isinstance(v,bool): return num_to_string(v)
        self.type_error_expected(callinfo,idx,"string",v)
    def opt_string(self,args,idx,default,callinfo):
        if idx>len(args) or args[idx-1] is NIL: return default
        return self.check_string(args,idx,callinfo)
    def check_number(self,args,idx,callinfo):
        if idx>len(args): self.type_error_expected(callinfo,idx,"number",_NOVALUE)
        v=args[idx-1]; n=to_number(v)
        if n is None: self.type_error_expected(callinfo,idx,"number",v)
        return n
    def opt_number(self,args,idx,default,callinfo):
        if idx>len(args) or args[idx-1] is NIL: return default
        return self.check_number(args,idx,callinfo)
    def check_integer(self,args,idx,callinfo):
        if idx>len(args): self.type_error_expected(callinfo,idx,"integer",_NOVALUE)
        v=args[idx-1]; n=to_integer(v)
        if n is None: self.type_error_expected(callinfo,idx,"integer",v)
        return n
    def opt_integer(self,args,idx,default,callinfo):
        if idx>len(args) or args[idx-1] is NIL: return default
        return self.check_integer(args,idx,callinfo)
    def check_table(self,args,idx,callinfo):
        if idx>len(args): self.type_error_expected(callinfo,idx,"table",_NOVALUE)
        v=args[idx-1]
        if not isinstance(v,LuaTable): self.type_error_expected(callinfo,idx,"table",v)
        return v
    def check_value(self,args,idx,callinfo):
        if idx>len(args):
            self.raise_err(f"bad argument #{idx} to '{callinfo.get('short','?')}' (value expected)".encode(),pseudo=["[C]: in ?"])
        return args[idx-1]
    # ---------- tostring ----------
    def tostring_bytes(self,v):
        if v is NIL: return b"nil"
        if isinstance(v,bool): return b"true" if v else b"false"
        if isinstance(v,(int,float)): return num_to_string(v)
        if isinstance(v,bytes): return v
        mt=self.get_metatable(v)
        if isinstance(mt,LuaTable):
            ts=mt.get(b"__tostring")
            if ts is not NIL:
                r=self.call_value(ts,[v],CallInfo(None,1,""),None)
                if r and isinstance(r[0],bytes): return r[0]
                return b""
        return f"{typename(v)}: 0x{self.addr(v):x}".encode()
    def get_metatable(self,v):
        if isinstance(v,LuaTable): return v.metatable or NIL
        if isinstance(v,bytes): return self.string_mt
        return NIL
    # ---------- loading / running ----------
    def load_chunk(self,source,chunkname,env_cell=None):
        toks=Lexer(source,chunkname).tokens()
        parser=Parser(toks,chunkname)
        body=parser.parse()
        scope=Scope(None,0)
        return LuaFunction([],True,body,scope,env_cell or self.global_env_cell,chunkname,1)
    def run_source(self,source,chunkname):
        fn=self.load_chunk(source,chunkname)
        return self.call_lua(fn,[],CallInfo("main",1,chunkname),main=True)
    # ---------- scope / globals ----------
    def get_global(self,frame,name):
        env=frame.env_cell.value if frame.env_cell else self.globals
        if isinstance(env,LuaTable):
            return self.index_value(env,name.encode(),None)
        return self.index_value(env,name.encode(),("global",name))
    def set_global(self,frame,name,v):
        env=frame.env_cell.value if frame.env_cell else self.globals
        self.newindex_value(env,name.encode(),v,("global",name))
    # ---------- calls ----------
    def call_value(self,fn,args,callinfo,hint):
        if isinstance(fn,BuiltinFunction):
            display=callinfo.display_name or fn.full
            ch=fn.chunk if hasattr(fn,'chunk') else "[C]"
            frame=CallFrame("C","[C]",name=display,line=callinfo.line)
            self.frames.append(frame)
            try:
                result=fn.fn(self,args,{"short":fn.short,"full":fn.full,"line":callinfo.line,"chunk":callinfo.chunk,"node":callinfo.node})
                if result is None: result=[]
                return result
            finally:
                self.frames.pop()
        if isinstance(fn,LuaFunction):
            return self.call_lua(fn,args,callinfo,hint=hint)
        # callable table
        mt=self.get_metatable(fn)
        if isinstance(mt,LuaTable):
            callmm=mt.get(b"__call")
            if callmm is not NIL:
                return self.call_value(callmm,[fn]+list(args),callinfo,hint)
        pseudo=[]
        if hint:
            pseudo=[f"[C]: in {hint[0]} '{hint[1]}'"]
        self.raise_err(f"attempt to call a {typename(fn)} value".encode()+self._hint_suffix(hint),pseudo=pseudo)
    def call_lua(self,fn,args,callinfo,hint=None,main=False):
        self._fid+=1; fid=self._fid
        scope=Scope(fn.scope,fid)
        varargs=[]
        for idx,pname in enumerate(fn.params):
            scope.declare(pname,args[idx] if idx<len(args) else NIL)
        if fn.vararg:
            varargs=list(args[len(fn.params):])
        name=None; kind="function"
        if hint:
            hk,hn=hint
            kind={"global":"global","local":"local","upvalue":"upvalue","field":"field","method":"method"}.get(hk,"function")
            name=hn
        fr=CallFrame("main" if main else "lua",fn.chunk,name=name,namekind=kind,line=fn.line,defline=fn.line,fid=fid,env_cell=fn.env_cell,varargs=varargs,func=fn)
        self.frames.append(fr)
        try:
            self.exec_block(fn.body,scope,fr,child=False)
            return []
        except ReturnExc as r:
            return r.vals
        finally:
            self.frames.pop()
    def _hint_suffix(self,hint):
        if hint: return f" ({hint[0]} '{hint[1]}')".encode()
        return b""
    # ---------- indexing ----------
    def index_value(self,obj,key,hint):
        if isinstance(obj,LuaTable):
            v=obj.get(key)
            if v is not NIL: return v
            mt=obj.metatable
            if isinstance(mt,LuaTable):
                mm=mt.get(b"__index")
                if isinstance(mm,LuaTable): return self.index_value(mm,key,hint)
                if mm is not NIL:
                    r=self.call_value(mm,[obj,key],CallInfo(None,self.frames[-1].line if self.frames else 1,self.frames[-1].chunk if self.frames else ""),None)
                    return r[0] if r else NIL
            return NIL
        if isinstance(obj,bytes):
            s=self.globals.get(b"string")
            if isinstance(s,LuaTable):
                # use raw lookup in string lib only
                v=s.get(key)
                return v
            return NIL
        if isinstance(obj,LuaFile):
            # file methods are looked up in io file metatable approx: provide via special table stored in globals
            ft=self.globals.get(b"__file_methods")
            if isinstance(ft,LuaTable): return ft.get(key)
            return NIL
        # userdata with metatable etc
        mt=self.get_metatable(obj)
        if isinstance(mt,LuaTable):
            mm=mt.get(b"__index")
            if isinstance(mm,LuaTable): return self.index_value(mm,key,hint)
            if mm is not NIL:
                r=self.call_value(mm,[obj,key],CallInfo(None,1,""),None); return r[0] if r else NIL
        self.raise_err(f"attempt to index a {typename(obj)} value".encode()+self._hint_suffix(hint),pseudo=["[C]: in metamethod 'index'"])
    def newindex_value(self,obj,key,v,hint):
        if isinstance(obj,LuaTable):
            if key is NIL: self.raise_err(b"table index is nil",pseudo=["[C]: in metamethod 'newindex'"])
            if isinstance(key,float) and math.isnan(key): self.raise_err(b"table index is NaN",pseudo=["[C]: in metamethod 'newindex'"])
            if obj.get(key) is NIL:
                mt=obj.metatable
                if isinstance(mt,LuaTable):
                    mm=mt.get(b"__newindex")
                    if isinstance(mm,LuaTable):
                        self.newindex_value(mm,key,v,hint); return
                    if mm is not NIL:
                        self.call_value(mm,[obj,key,v],CallInfo(None,1,""),None); return
            obj.set(key,v); return
        self.raise_err(f"attempt to index a {typename(obj)} value".encode()+self._hint_suffix(hint),pseudo=["[C]: in metamethod 'newindex'"])
    # ---------- execution ----------
    def exec_block(self,nodes,scope,frame,child=True):
        sc=Scope(scope,frame.fid) if child else scope
        i=0
        while i<len(nodes):
            node=nodes[i]
            try:
                self.exec_stmt(node,sc,frame)
            except GotoExc as g:
                # search label in this block
                found=None
                for idx,nd in enumerate(nodes):
                    if nd["k"]=="label" and nd["name"]==g.name: found=idx; break
                if found is None: raise
                i=found+1; continue
            i+=1
    def exec_stmt(self,node,scope,frame):
        frame.line=node["line"]
        k=node["k"]
        if k=="do": self.exec_block(node["body"],scope,frame,child=True)
        elif k=="callstmt": self.eval_expr_multi(node["expr"],scope,frame)
        elif k=="return":
            vals=self.eval_exprlist(node["exprs"],scope,frame); raise ReturnExc(vals)
        elif k=="break": raise BreakExc()
        elif k=="goto": raise GotoExc(node["name"])
        elif k=="label": pass
        elif k=="local":
            vals=self.eval_exprlist(node["exprs"],scope,frame) if node["exprs"] else []
            for idx,name in enumerate(node["names"]):
                scope.declare(name,vals[idx] if idx<len(vals) else NIL)
        elif k=="localfunc":
            cell=scope.declare(node["name"],NIL)
            fn=self.make_function(node["func"],scope,frame)
            cell.value=fn
        elif k=="assign":
            vals=self.eval_exprlist(node["exprs"],scope,frame)
            for idx,target in enumerate(node["targets"]):
                v=vals[idx] if idx<len(vals) else NIL
                self.assign_target(target,v,scope,frame)
        elif k=="while":
            while truthy(self.eval_expr(node["cond"],scope,frame)):
                try: self.exec_block(node["body"],scope,frame,child=True)
                except BreakExc: break
        elif k=="repeat":
            while True:
                sc=Scope(scope,frame.fid)
                try: self.exec_block(node["body"],sc,frame,child=False)
                except BreakExc: break
                frame.line=node["line"]
                if truthy(self.eval_expr(node["cond"],sc,frame)): break
        elif k=="if":
            done=False
            for cond,body in node["branches"]:
                if truthy(self.eval_expr(cond,scope,frame)):
                    self.exec_block(body,scope,frame,child=True); done=True; break
            if not done and node.get("elsebody") is not None:
                self.exec_block(node["elsebody"],scope,frame,child=True)
        elif k=="fornum":
            start=self.eval_expr(node["start"],scope,frame); limit=self.eval_expr(node["limit"],scope,frame); step=self.eval_expr(node["step"],scope,frame) if node.get("step") else 1
            si=to_integer(start); li=to_integer(limit); sti=to_integer(step)
            if si is not None and li is not None and sti is not None:
                if sti==0: self.raise_err(b"'for' step is zero")
                cur=si
                while (cur<=li if sti>0 else cur>=li):
                    sc=Scope(scope,frame.fid); sc.declare(node["name"],cur)
                    try: self.exec_block(node["body"],sc,frame,child=False)
                    except BreakExc: break
                    cur=wrap_i64(cur+sti)
            else:
                sf=to_number(start); lf=to_number(limit); stf=to_number(step)
                if sf is None: self.raise_err(b"'for' initial value must be a number")
                if lf is None: self.raise_err(b"'for' limit must be a number")
                if stf is None: self.raise_err(b"'for' step must be a number")
                if stf==0: self.raise_err(b"'for' step is zero")
                cur=float(sf)
                while (cur<=lf if stf>0 else cur>=lf):
                    sc=Scope(scope,frame.fid); sc.declare(node["name"],cur)
                    try: self.exec_block(node["body"],sc,frame,child=False)
                    except BreakExc: break
                    cur+=stf
        elif k=="forgen":
            vals=self.eval_exprlist(node["exprs"],scope,frame)
            iterfn=vals[0] if len(vals)>0 else NIL; state=vals[1] if len(vals)>1 else NIL; ctrl=vals[2] if len(vals)>2 else NIL
            while True:
                results=self.call_value(iterfn,[state,ctrl],CallInfo(None,node["line"],frame.chunk,node),None)
                if not results or results[0] is NIL: break
                ctrl=results[0]
                sc=Scope(scope,frame.fid)
                for idx,name in enumerate(node["names"]):
                    sc.declare(name,results[idx] if idx<len(results) else NIL)
                try: self.exec_block(node["body"],sc,frame,child=False)
                except BreakExc: break
        else:
            pass
    def make_function(self,node,scope,frame):
        # determine env cell: explicit local _ENV in scope chain else frame env
        cell,found=scope.find("_ENV")
        env_cell=cell if cell is not None else frame.env_cell
        return LuaFunction(node["params"],node["vararg"],node["body"],scope,env_cell,frame.chunk,node["line"])
    def assign_target(self,target,v,scope,frame):
        k=target["k"]
        frame.line=target["line"]
        if k=="var":
            name=target["name"]
            if name=="_ENV":
                cell,_=scope.find("_ENV")
                if cell is not None: cell.value=v; return
                frame.env_cell.value=v; return
            cell,_=scope.find(name)
            if cell is not None: cell.value=v
            else: self.set_global(frame,name,v)
            return
        if k=="field":
            obj=self.eval_expr(target["obj"],scope,frame)
            self.newindex_value(obj,target["name"].encode(),v,self.name_hint(target["obj"],scope,frame)); return
        if k=="index":
            obj=self.eval_expr(target["obj"],scope,frame); key=self.eval_expr(target["key"],scope,frame)
            self.newindex_value(obj,key,v,self.name_hint(target["obj"],scope,frame)); return
        if k=="paren":
            self.assign_target(target["expr"],v,scope,frame); return
    def eval_exprlist(self,exprs,scope,frame):
        out=[]
        for i,e in enumerate(exprs):
            if i==len(exprs)-1:
                out.extend(self.eval_expr_multi(e,scope,frame))
            else:
                out.append(self.eval_expr(e,scope,frame))
        return out
    def name_hint(self,node,scope,frame):
        if node["k"]=="var":
            name=node["name"]
            cell,owner=scope.find(name)
            if cell is not None:
                kind="local" if owner.function_id==frame.fid else "upvalue"
                return (kind,name)
            return ("global",name)
        if node["k"]=="field": return ("field",node["name"])
        if node["k"]=="index" and node["key"]["k"]=="str": return ("field",node["key"]["value"].decode('utf-8','replace'))
        if node["k"]=="mcall": return ("method",node["name"])
        return None
    def eval_expr(self,node,scope,frame):
        vals=self.eval_expr_multi(node,scope,frame,trunc=True)
        return vals[0] if vals else NIL
    def eval_expr_multi(self,node,scope,frame,trunc=False):
        frame.line=node["line"]
        k=node["k"]
        if k=="call":
            fn=self.eval_expr(node["fn"],scope,frame)
            args=self.eval_exprlist(node["args"],scope,frame)
            info=CallInfo(self.call_display(node["fn"],scope,frame),node["line"],frame.chunk,node)
            result=self.call_value(fn,args,info,self.name_hint(node["fn"],scope,frame))
            return result[:1] if trunc else result
        if k=="mcall":
            obj=self.eval_expr(node["obj"],scope,frame)
            fn=self.index_value(obj,node["name"].encode(),self.name_hint(node["obj"],scope,frame))
            args=[obj]+self.eval_exprlist(node["args"],scope,frame)
            # display name for method: obj display + :name is not Lua trace; use method name
            info=CallInfo(node["name"],node["line"],frame.chunk,node)
            result=self.call_value(fn,args,info,("method",node["name"]))
            return result[:1] if trunc else result
        if k=="vararg":
            vals=list(frame.varargs); return vals[:1] if trunc else (vals if vals else [NIL])
        return [self._eval_single(node,scope,frame)]
    def call_display(self,node,scope,frame):
        # build dotted display for C function names: string.find etc
        if node["k"]=="var": return node["name"]
        if node["k"]=="field":
            base=self.call_display(node["obj"],scope,frame)
            return f"{base}.{node['name']}" if base else node["name"]
        if node["k"]=="index" and node["key"]["k"]=="str":
            base=self.call_display(node["obj"],scope,frame); key=node["key"]["value"].decode('utf-8','replace')
            return f"{base}.{key}" if base else key
        return None
    def _eval_single(self,node,scope,frame):
        frame.line=node["line"]; k=node["k"]
        if k=="nil": return NIL
        if k=="bool": return node["value"]
        if k=="num": return node["value"]
        if k=="str": return node["value"]
        if k=="paren": return self.eval_expr(node["expr"],scope,frame)
        if k=="var":
            name=node["name"]
            if name=="_ENV":
                cell,_=scope.find("_ENV")
                if cell is not None: return cell.value
                return frame.env_cell.value
            cell,_=scope.find(name)
            if cell is not None: return cell.value
            return self.get_global(frame,name)
        if k=="field":
            obj=self.eval_expr(node["obj"],scope,frame)
            return self.index_value(obj,node["name"].encode(),self.name_hint(node["obj"],scope,frame))
        if k=="index":
            obj=self.eval_expr(node["obj"],scope,frame); key=self.eval_expr(node["key"],scope,frame)
            return self.index_value(obj,key,self.name_hint(node["obj"],scope,frame))
        if k=="table":
            tbl=LuaTable(); pos=1
            fields=node["fields"]
            for fi,field in enumerate(fields):
                if field[0]=="pos":
                    if fi==len(fields)-1:
                        vals=self.eval_expr_multi(field[1],scope,frame)
                        for v in vals: tbl.set(pos,v); pos+=1
                    else:
                        tbl.set(pos,self.eval_expr(field[1],scope,frame)); pos+=1
                elif field[0]=="name":
                    tbl.set(field[1].encode(),self.eval_expr(field[2],scope,frame))
                else:
                    key=self.eval_expr(field[1],scope,frame); v=self.eval_expr(field[2],scope,frame)
                    if key is NIL: self.raise_err(b"table index is nil")
                    tbl.set(key,v)
            return tbl
        if k=="function": return self.make_function(node,scope,frame)
        if k=="unop":
            op=node["op"]; hint=self.name_hint(node["expr"],scope,frame); v=self.eval_expr(node["expr"],scope,frame)
            frame.line=node["line"]
            if op=="not": return not truthy(v)
            if op=="#":
                if isinstance(v,bytes): return len(v)
                if isinstance(v,LuaTable):
                    mt=v.metatable
                    if isinstance(mt,LuaTable) and mt.get(b"__len") is not NIL:
                        r=self.call_value(mt.get(b"__len"),[v],CallInfo(None,node["line"],frame.chunk,node),None); return r[0] if r else NIL
                    return v.rawlen()
                mt=self.get_metatable(v)
                if isinstance(mt,LuaTable) and mt.get(b"__len") is not NIL:
                    r=self.call_value(mt.get(b"__len"),[v],CallInfo(None,node["line"],frame.chunk,node),None); return r[0] if r else NIL
                self.raise_err(f"attempt to get length of a {typename(v)} value".encode()+self._hint_suffix(hint),pseudo=["[C]: in metamethod 'len'"])
            if op=="-":
                mm=self.metamethod(v,b"__unm")
                if mm is not None:
                    r=self.call_value(mm,[v],CallInfo(None,node["line"],frame.chunk,node),None); return r[0] if r else NIL
                n=to_number(v)
                if n is None:
                    self.raise_err(f"attempt to perform arithmetic on a {typename(v)} value".encode()+self._hint_suffix(hint),pseudo=["[C]: in metamethod 'unm'"])
