        while b"\n" not in self.buf and not self.eof:
            try:
                chunk = os.read(self.fd, 65536)
            except BlockingIOError:
                chunk = b""
            except OSError as e:
                return ("ERROR", f"{e.strerror} (os error {e.errno})" if e.errno else str(e))
