        ts_raw = extract_value(entry, time_keys)
        fblog_timestamp = convert_timestamp(ts_raw) if ts_raw is not None else ""
        level_raw = extract_value(entry, level_keys)
        fblog_level = level_map.get(level_raw if level_raw is not None else "unknown", level_raw if level_raw is not None else "unknown")
        msg_raw = extract_value(entry, message_keys)
        fblog_message = msg_raw if msg_raw is not None else ""
        if subst_enabled and context_key in entry:
            fblog_message = substitute(fblog_message, entry[context_key], sub_prefix, sub_suffix)
        # filter
        if args.filter is not None:
            lines_lua = lua_init_lines(entry)
            if args.print_lua:
                for ll in lines_lua:
                    write_stdout(ll + "\n")
            init_src = "\n".join(lines_lua)
            if args.no_implicit_filter_return_statement:
                filter_src = args.filter; chunk = "src/filter.rs:25"
            else:
                filter_src = "return " + args.filter; chunk = "src/filter.rs:23"
            passed, err = lua_mod.evaluate_filter(init_src, filter_src, chunk, output_fn=write_stdout)
            if err is not None:
                write_stderr(f"\x1b[31mFailed to apply filter expression\x1b[0m: '{err}'\n")
                continue
            if not passed:
                continue
        # main context
        context = dict(entry)
        context["fblog_timestamp"] = fblog_timestamp
        context["fblog_level"] = fblog_level
        context["fblog_message"] = fblog_message
        context["fblog_prefix"] = prefix
        context = {k: context[k] for k in sorted(context.keys())}
        flat = flatten(entry)
        # main line
        try:
            rendered = main_tpl.render(context)
            write_stdout(rendered + "\n")
        except RenderError as e:
            write_stdout(f"{RED_Q} Failed to process line: {e.full('main_line')}\n")
        # additional values
        if dump_all:
            selected = [(k, v) for k, v in flat if k not in excluded]
        else:
            selected = []
            for sel in list(cfg.always_print_fields) + list(args.additional_value):
                for k, v in flat:
                    if selector_matches(k, sel): selected.append((k, v))
        for k, v in selected:
            try:
                rendered = add_tpl.render({"key": k, "value": v})
                write_stdout(rendered + "\n")
            except RenderError as e:
                write_stdout(f"{RED_Q3} Failed to process additional value: {e.full('additional_value')}\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
