def _sanitize_lua_key(k):
    return "".join(c if (('A'<=c<='Z') or ('a'<=c<='z') or c=='_') else '_' for c in k)

def _init_keys_valid(v):
    if isinstance(v,dict):
        for k,val in v.items():
            sk=_sanitize_lua_key(k)
            if sk=="" or sk in KEYWORDS:
                return False
            if not _init_keys_valid(val):
                return False
    elif isinstance(v,list):
        # objects inside arrays become "unsupported" and are never converted, so keys inside them don't matter
        return True
    return True

def _json_to_lua(v):
    if isinstance(v,dict):
        t=LuaTable()
        for k,val in v.items():
            t.set(_sanitize_lua_key(k).encode(), _json_to_lua(val))
        return t
    if isinstance(v,list):
        t=LuaTable()
        for i,e in enumerate(v):
            if isinstance(e,str): lv=e.encode('utf-8','surrogateescape')
            elif e is True: lv=True
            elif e is False: lv=False
            elif isinstance(e,int): lv=wrap_i64(e)
            elif isinstance(e,float): lv=e
            else: lv=b"unsupported"
            t.set(i+1,lv)
        return t
    if isinstance(v,str): return v.encode('utf-8','surrogateescape')
    if v is True: return True
    if v is False: return False
    if isinstance(v,int): return wrap_i64(v)
    if isinstance(v,float): return v
    return b"unsupported"

class PreparedFilter:
    def __init__(self, filter_source, filter_chunk):
        self.chunk=filter_chunk
        self.body=None; self.syntax_error=None
        try:
            toks=Lexer(filter_source,filter_chunk).tokens()
            self.body=Parser(toks,filter_chunk).parse()
        except LuaSyntaxError as e:
            self.syntax_error=e
        self._scope_template=Scope(None,0)
    def evaluate(self, init_source, output_fn=None, init_entry=None):
        interp=Interp(output_fn=output_fn)
        try:
            # init first (its errors take precedence)
            direct=False
            if init_entry is not None:
                top_names=[_sanitize_lua_key(k) for k in init_entry.keys()]
                if "_ENV" not in top_names and _init_keys_valid(init_entry):
                    direct=True
                    for k,v in init_entry.items():
                        interp.globals.set(_sanitize_lua_key(k).encode(), _json_to_lua(v))
            if not direct and init_source:
                interp.run_source(init_source,"src/filter.rs:20")
            if self.syntax_error is not None:
                raise self.syntax_error
            fn=LuaFunction([],True,self.body,self._scope_template,interp.global_env_cell,self.chunk,1)
            result=interp.call_lua(fn,[],CallInfo("main",1,self.chunk),main=True)
        except LuaSyntaxError as e:
            return False, e.debug()
        except LuaRuntimeErr as e:
            try: return False, format_runtime_error(interp,e)
            except Exception: return False, 'RuntimeError("error")'
        except RecursionError:
            return False, 'RuntimeError("stack overflow")'
        except Exception as e:
            return False, 'RuntimeError(' + _dbg(str(e)) + ')'
        first=result[0] if result else NIL
        return truthy(first), None
